239|// String utilities
240|PUGI_IMPL_NS_BEGIN
241|	// Get string length
242|	PUGI_IMPL_FN size_t strlength(const char_t* s)
243|	{
244|		assert(s);
245|
246|	#ifdef PUGIXML_WCHAR_MODE
247|		return wcslen(s);
248|	#else
249|		return strlen(s);
250|	#endif
251|	}
252|
253|	// Compare two strings
254|	PUGI_IMPL_FN bool strequal(const char_t* src, const char_t* dst)
255|	{
256|		assert(src && dst);
257|
258|	#ifdef PUGIXML_WCHAR_MODE
259|		return *src == *dst && wcscmp(src, dst) == 0;
260|	#else
261|		return *src == *dst && strcmp(src, dst) == 0;
262|	#endif
263|	}
264|
265|#ifdef PUGIXML_HAS_STRING_VIEW
266|	// Check if the null-terminated dst string is equal to the entire contents of srcview
267|	PUGI_IMPL_FN bool stringview_equal(string_view_t srcview, const char_t* dst)
268|	{
269|		// std::basic_string_view::compare(const char*) has the right behavior, but it performs an
270|		// extra traversal of dst to compute its length.
271|		assert(dst);
272|		const char_t* src = srcview.data();
273|		size_t srclen = srcview.size();
274|
275|		while (srclen && *dst && *src == *dst)
276|		{
277|			--srclen; ++dst; ++src;
278|		}
279|		return srclen == 0 && *dst == 0;
280|	}
281|#endif
282|
283|	// Compare lhs with [rhs, rhs + count)
284|	PUGI_IMPL_FN bool strequalrange(const char_t* lhs, const char_t* rhs, size_t count)
285|	{
286|		for (size_t i = 0; i < count; ++i)
287|			if (lhs[i] != rhs[i])
288|				return false;
289|
290|		return lhs[count] == 0;
291|	}
292|
293|	// Get length of wide string, even if CRT lacks wide character support
294|	PUGI_IMPL_FN size_t strlength_wide(const wchar_t* s)
295|	{
296|		assert(s);
297|
298|	#ifdef PUGIXML_WCHAR_MODE
299|		return wcslen(s);
300|	#else
301|		const wchar_t* end = s;
302|		while (*end) end++;
303|		return static_cast<size_t>(end - s);
304|	#endif
305|	}
306|PUGI_IMPL_NS_END
