309|PUGI_IMPL_NS_BEGIN
310|	template <typename T> struct auto_deleter
311|	{
312|		typedef void (*D)(T*);
313|
314|		T* data;
315|		D deleter;
316|
317|		auto_deleter(T* data_, D deleter_): data(data_), deleter(deleter_)
318|		{
319|		}
320|
321|		~auto_deleter()
322|		{
323|			if (data) deleter(data);
324|		}
325|
326|		T* release()
327|		{
328|			T* result = data;
329|			data = NULL;
330|			return result;
331|		}
332|	};
