335|#ifdef PUGIXML_COMPACT
336|PUGI_IMPL_NS_BEGIN
337|	class compact_hash_table
338|	{
339|	public:
340|		compact_hash_table(): _items(NULL), _capacity(0), _count(0)
341|		{
342|		}
343|
344|		void clear()
345|		{
346|			if (_items)
347|			{
348|				xml_memory::deallocate(_items);
349|				_items = NULL;
350|				_capacity = 0;
351|				_count = 0;
352|			}
353|		}
354|
355|		void* find(const void* key)
356|		{
357|			if (_capacity == 0) return NULL;
358|
359|			item_t* item = get_item(key);
360|			assert(item);
361|			assert(item->key == key || (item->key == NULL && item->value == NULL));
362|
363|			return item->value;
364|		}
365|
366|		void insert(const void* key, void* value)
367|		{
368|			assert(_capacity != 0 && _count < _capacity - _capacity / 4);
369|
370|			item_t* item = get_item(key);
371|			assert(item);
372|
373|			if (item->key == NULL)
374|			{
375|				_count++;
376|				item->key = key;
377|			}
378|
379|			item->value = value;
380|		}
381|
382|		bool reserve(size_t extra = 16)
383|		{
384|			if (_count + extra >= _capacity - _capacity / 4)
385|				return rehash(_count + extra);
386|
387|			return true;
388|		}
389|
390|	private:
391|		struct item_t
392|		{
393|			const void* key;
394|			void* value;
395|		};
396|
397|		item_t* _items;
398|		size_t _capacity;
399|
400|		size_t _count;
401|
402|		bool rehash(size_t count);
403|
404|		item_t* get_item(const void* key)
405|		{
406|			assert(key);
407|			assert(_capacity > 0);
408|
409|			size_t hashmod = _capacity - 1;
410|			size_t bucket = hash(key) & hashmod;
411|
412|			for (size_t probe = 0; probe <= hashmod; ++probe)
413|			{
414|				item_t& probe_item = _items[bucket];
415|
416|				if (probe_item.key == key || probe_item.key == NULL)
417|					return &probe_item;
418|
419|				// hash collision, quadratic probing
420|				bucket = (bucket + probe + 1) & hashmod;
421|			}
422|
423|			assert(false && "Hash table is full"); // unreachable
424|			return NULL;
425|		}
426|
427|		static PUGI_IMPL_UNSIGNED_OVERFLOW unsigned int hash(const void* key)
428|		{
429|			unsigned int h = static_cast<unsigned int>(reinterpret_cast<uintptr_t>(key) & 0xffffffff);
430|
431|			// MurmurHash3 32-bit finalizer
432|			h ^= h >> 16;
433|			h *= 0x85ebca6bu;
434|			h ^= h >> 13;
435|			h *= 0xc2b2ae35u;
436|			h ^= h >> 16;
437|
438|			return h;
439|		}
440|	};
441|
442|	PUGI_IMPL_FN_NO_INLINE bool compact_hash_table::rehash(size_t count)
443|	{
444|		size_t capacity = 32;
445|		while (count >= capacity - capacity / 4)
446|			capacity *= 2;
447|
448|		compact_hash_table rt;
449|		rt._capacity = capacity;
450|		rt._items = static_cast<item_t*>(xml_memory::allocate(sizeof(item_t) * capacity));
451|
452|		if (!rt._items)
453|			return false;
454|
455|		memset(rt._items, 0, sizeof(item_t) * capacity);
456|
457|		for (size_t i = 0; i < _capacity; ++i)
458|			if (_items[i].key)
459|				rt.insert(_items[i].key, _items[i].value);
460|
461|		if (_items)
462|			xml_memory::deallocate(_items);
463|
464|		_capacity = capacity;
465|		_items = rt._items;
466|
467|		assert(_count == rt._count);
468|
469|		return true;
470|	}
471|
472|PUGI_IMPL_NS_END
473|#endif
