541|
542|	static const size_t xml_memory_page_size =
543|	#ifdef PUGIXML_MEMORY_PAGE_SIZE
544|		(PUGIXML_MEMORY_PAGE_SIZE)
545|	#else
546|		32768
547|	#endif
548|		- sizeof(xml_memory_page);
