550|	struct xml_memory_string_header
551|	{
552|		uint16_t page_offset; // offset from page->data
553|		uint16_t full_size; // 0 if string occupies whole page
554|	};
555|
556|	struct xml_allocator
557|	{
558|		xml_allocator(xml_memory_page* root): _root(root), _busy_size(root->busy_size)
559|		{
560|		#ifdef PUGIXML_COMPACT
561|			_hash = NULL;
562|		#endif
563|		}
564|
565|		xml_memory_page* allocate_page(size_t data_size)
566|		{
567|			size_t size = sizeof(xml_memory_page) + data_size;
568|
569|			// allocate block with some alignment, leaving memory for worst-case padding
570|			void* memory = xml_memory::allocate(size);
571|			if (!memory) return NULL;
572|
573|			// prepare page structure
574|			xml_memory_page* page = xml_memory_page::construct(memory);
575|			assert(page);
576|
577|			assert(this == _root->allocator);
578|			page->allocator = this;
579|
580|			return page;
581|		}
582|
583|		static void deallocate_page(xml_memory_page* page)
584|		{
585|			xml_memory::deallocate(page);
586|		}
587|
588|		void* allocate_memory_oob(size_t size, xml_memory_page*& out_page);
589|
590|		void* allocate_memory(size_t size, xml_memory_page*& out_page)
591|		{
592|			if (PUGI_IMPL_UNLIKELY(_busy_size + size > xml_memory_page_size))
593|				return allocate_memory_oob(size, out_page);
594|
595|			void* buf = reinterpret_cast<char*>(_root) + sizeof(xml_memory_page) + _busy_size;
596|
597|			_busy_size += size;
598|
599|			out_page = _root;
600|
601|			return buf;
602|		}
603|
604|	#ifdef PUGIXML_COMPACT
605|		void* allocate_object(size_t size, xml_memory_page*& out_page)
606|		{
607|			void* result = allocate_memory(size + sizeof(uint32_t), out_page);
608|			if (!result) return NULL;
609|
610|			// adjust for marker
611|			ptrdiff_t offset = static_cast<char*>(result) - reinterpret_cast<char*>(out_page->compact_page_marker);
612|
613|			if (PUGI_IMPL_UNLIKELY(static_cast<uintptr_t>(offset) >= 256 * xml_memory_block_alignment))
614|			{
615|				// insert new marker
616|				uint32_t* marker = static_cast<uint32_t*>(result);
617|
618|				*marker = static_cast<uint32_t>(reinterpret_cast<char*>(marker) - reinterpret_cast<char*>(out_page));
619|				out_page->compact_page_marker = marker;
620|
