1706|		template <typename Traits> static inline typename Traits::value_type process(const uint8_t* data, size_t size, typename Traits::value_type result, Traits)
1707|		{
1708|			const uint8_t utf8_byte_mask = 0x3f;
1709|
1710|			while (size)
1711|			{
1712|				uint8_t lead = *data;
1713|
1714|				// 0xxxxxxx -> U+0000..U+007F
1715|				if (lead < 0x80)
1716|				{
1717|					result = Traits::low(result, lead);
1718|					data += 1;
1719|					size -= 1;
1720|
1721|					// process aligned single-byte (ascii) blocks
1722|					if ((reinterpret_cast<uintptr_t>(data) & 3) == 0)
1723|					{
1724|						// round-trip through void* to silence 'cast increases required alignment of target type' warnings
1725|						while (size >= 4 && (*static_cast<const uint32_t*>(static_cast<const void*>(data)) & 0x80808080) == 0)
1726|						{
1727|							result = Traits::low(result, data[0]);
1728|							result = Traits::low(result, data[1]);
1729|							result = Traits::low(result, data[2]);
1730|							result = Traits::low(result, data[3]);
1731|							data += 4;
1732|							size -= 4;
1733|						}
1734|					}
1735|				}
1736|				// 110xxxxx -> U+0080..U+07FF
1737|				else if (static_cast<unsigned int>(lead - 0xC0) < 0x20 && size >= 2 && (data[1] & 0xc0) == 0x80)
1738|				{
1739|					result = Traits::low(result, ((lead & ~0xC0) << 6) | (data[1] & utf8_byte_mask));
1740|					data += 2;
1741|					size -= 2;
1742|				}
1743|				// 1110xxxx -> U+0800-U+FFFF
1744|				else if (static_cast<unsigned int>(lead - 0xE0) < 0x10 && size >= 3 && (data[1] & 0xc0) == 0x80 && (data[2] & 0xc0) == 0x80)
1745|				{
1746|					result = Traits::low(result, ((lead & ~0xE0) << 12) | ((data[1] & utf8_byte_mask) << 6) | (data[2] & utf8_byte_mask));
1747|					data += 3;
1748|					size -= 3;
1749|				}
1750|				// 11110xxx -> U+10000..U+10FFFF
1751|				else if (static_cast<unsigned int>(lead - 0xF0) < 0x08 && size >= 4 && (data[1] & 0xc0) == 0x80 && (data[2] & 0xc0) == 0x80 && (data[3] & 0xc0) == 0x80)
1752|				{
1753|					result = Traits::high(result, ((lead & ~0xF0) << 18) | ((data[1] & utf8_byte_mask) << 12) | ((data[2] & utf8_byte_mask) << 6) | (data[3] & utf8_byte_mask));
1754|					data += 4;
1755|					size -= 4;
1756|				}
1757|				// 10xxxxxx or 11111xxx -> invalid
1758|				else
1759|				{
1760|					data += 1;
1761|					size -= 1;
1762|				}
1763|			}
1764|
1765|			return result;
