2011|		for (size_t i = 6; i + 1 < size; ++i)
2012|		{
2013|			// declaration can not contain ? in quoted values
2014|			if (data[i] == '?')
2015|				return false;
2016|
2017|			if (data[i] == 'e' && data[i + 1] == 'n')
2018|			{
2019|				size_t offset = i;
