2022|				PUGI_IMPL_SCANCHAR('e'); PUGI_IMPL_SCANCHAR('n'); PUGI_IMPL_SCANCHAR('c'); PUGI_IMPL_SCANCHAR('o');
2023|				PUGI_IMPL_SCANCHAR('d'); PUGI_IMPL_SCANCHAR('i'); PUGI_IMPL_SCANCHAR('n'); PUGI_IMPL_SCANCHAR('g');
2024|
2025|				// S? = S?
2026|				PUGI_IMPL_SCANCHARTYPE(ct_space);
2027|				PUGI_IMPL_SCANCHAR('=');
2028|				PUGI_IMPL_SCANCHARTYPE(ct_space);
2029|
2030|				// the only two valid delimiters are ' and "
2031|				uint8_t delimiter = (offset < size && data[offset] == '"') ? '"' : '\'';
2032|
2033|				PUGI_IMPL_SCANCHAR(delimiter);
2034|
2035|				size_t start = offset;
2036|
2037|				out_encoding = data + offset;
2038|
2039|				PUGI_IMPL_SCANCHARTYPE(ct_symbol);
2040|
2041|				out_length = offset - start;
2042|
2043|				PUGI_IMPL_SCANCHAR(delimiter);
2044|
2045|				return true;
2046|			}
2047|		}
2048|
2049|		return false;
