2064|		if (d0 == 0xff && d1 == 0xfe && d2 == 0 && d3 == 0) return encoding_utf32_le;
2065|		if (d0 == 0xfe && d1 == 0xff) return encoding_utf16_be;
2066|		if (d0 == 0xff && d1 == 0xfe) return encoding_utf16_le;
2067|		if (d0 == 0xef && d1 == 0xbb && d2 == 0xbf) return encoding_utf8;
2068|
2069|		// look for <, <? or <?xm in various encodings
2070|		if (d0 == 0 && d1 == 0 && d2 == 0 && d3 == 0x3c) return encoding_utf32_be;
2071|		if (d0 == 0x3c && d1 == 0 && d2 == 0 && d3 == 0) return encoding_utf32_le;
2072|		if (d0 == 0 && d1 == 0x3c && d2 == 0 && d3 == 0x3f) return encoding_utf16_be;
2073|		if (d0 == 0x3c && d1 == 0 && d2 == 0x3f && d3 == 0) return encoding_utf16_le;
2074|
2075|		// look for utf16 < followed by node name (this may fail, but is better than utf8 since it's zero terminated so early)
2076|		if (d0 == 0 && d1 == 0x3c) return encoding_utf16_be;
2077|		if (d0 == 0x3c && d1 == 0) return encoding_utf16_le;
2078|
2079|		// no known BOM detected; parse declaration
2080|		const uint8_t* enc = NULL;
2081|		size_t enc_length = 0;
2082|
2083|		if (d0 == 0x3c && d1 == 0x3f && d2 == 0x78 && d3 == 0x6d && parse_declaration_encoding(data, size, enc, enc_length))
2084|		{
2085|			// iso-8859-1 (case-insensitive)
2086|			if (enc_length == 10
2087|				&& (enc[0] | ' ') == 'i' && (enc[1] | ' ') == 's' && (enc[2] | ' ') == 'o'
2088|				&& enc[3] == '-' && enc[4] == '8' && enc[5] == '8' && enc[6] == '5' && enc[7] == '9'
2089|				&& enc[8] == '-' && enc[9] == '1')
2090|				return encoding_latin1;
2091|
2092|			// latin1 (case-insensitive)
2093|			if (enc_length == 6
2094|				&& (enc[0] | ' ') == 'l' && (enc[1] | ' ') == 'a' && (enc[2] | ' ') == 't'
2095|				&& (enc[3] | ' ') == 'i' && (enc[4] | ' ') == 'n'
2096|				&& enc[5] == '1')
