2291|	PUGI_IMPL_FN bool convert_buffer_latin1(char_t*& out_buffer, size_t& out_length, const void* contents, size_t size, bool is_mutable)
2292|	{
2293|		const uint8_t* data = static_cast<const uint8_t*>(contents);
2294|		size_t data_length = size;
2295|
2296|		// get size of prefix that does not need utf8 conversion
2297|		size_t prefix_length = get_latin1_7bit_prefix_length(data, data_length);
2298|		assert(prefix_length <= data_length);
2299|
2300|		const uint8_t* postfix = data + prefix_length;
2301|		size_t postfix_length = data_length - prefix_length;
2302|
2303|		// if no conversion is needed, just return the original buffer
2304|		if (postfix_length == 0) return get_mutable_buffer(out_buffer, out_length, contents, size, is_mutable);
2305|
2306|		// first pass: get length in utf8 units
2307|		size_t length = prefix_length + latin1_decoder::process(postfix, postfix_length, 0, utf8_counter());
2308|
2309|		// allocate buffer of suitable length
2310|		char_t* buffer = static_cast<char_t*>(xml_memory::allocate((length + 1) * sizeof(char_t)));
2311|		if (!buffer) return false;
2312|
2313|		// second pass: convert latin1 input to utf8
2314|		memcpy(buffer, data, prefix_length);
2315|
2316|		uint8_t* obegin = reinterpret_cast<uint8_t*>(buffer);
2317|		uint8_t* oend = latin1_decoder::process(postfix, postfix_length, obegin + prefix_length, utf8_writer());
2318|
2319|		assert(oend == obegin + length);
2320|		*oend = 0;
2321|
2322|		out_buffer = buffer;
2323|		out_length = length + 1;
2324|
2325|		return true;
2326|	}
