2421|	template <typename Header>
2422|	inline bool strcpy_insitu_allow(size_t length, const Header& header, uintptr_t header_mask, char_t* target)
2423|	{
2424|		// never reuse shared memory
2425|		if (header & xml_memory_page_contents_shared_mask) return false;
2426|
2427|		size_t target_length = strlength(target);
2428|
2429|		// always reuse document buffer memory if possible
2430|		if ((header & header_mask) == 0) return target_length >= length;
2431|
2432|		// reuse heap memory if waste is not too great
2433|		const size_t reuse_threshold = 32;
2434|
2435|		return target_length >= length && (target_length < reuse_threshold || target_length - length < target_length / 2);
2436|	}
