2438|	template <typename String, typename Header>
2439|	PUGI_IMPL_FN bool strcpy_insitu(String& dest, Header& header, uintptr_t header_mask, const char_t* source, size_t source_length)
2440|	{
2441|		assert((header & header_mask) == 0 || dest); // header bit indicates whether dest was previously allocated
2442|
2443|		if (source_length == 0)
2444|		{
2445|			// empty string and null pointer are equivalent, so just deallocate old memory
2446|			xml_allocator* alloc = PUGI_IMPL_GETPAGE_IMPL(header)->allocator;
2447|
2448|			if (header & header_mask) alloc->deallocate_string(dest);
2449|
2450|			// mark the string as not allocated
2451|			dest = NULL;
2452|			header &= ~header_mask;
2453|
2454|			return true;
2455|		}
2456|		else if (dest && strcpy_insitu_allow(source_length, header, header_mask, dest))
2457|		{
2458|			// we can reuse old buffer, so just copy the new data (including zero terminator)
2459|			memcpy(dest, source, source_length * sizeof(char_t));
2460|			dest[source_length] = 0;
2461|
2462|			return true;
2463|		}
2464|		else
2465|		{
2466|			xml_allocator* alloc = PUGI_IMPL_GETPAGE_IMPL(header)->allocator;
2467|
2468|			if (!alloc->reserve()) return false;
2469|
2470|			// allocate new buffer
2471|			char_t* buf = alloc->allocate_string(source_length + 1);
2472|			if (!buf) return false;
2473|
2474|			// copy the string (including zero terminator)
2475|			memcpy(buf, source, source_length * sizeof(char_t));
2476|			buf[source_length] = 0;
2477|
2478|			// deallocate old buffer (*after* the above to protect against overlapping memory and/or allocation failures)
2479|			if (header & header_mask) alloc->deallocate_string(dest);
2480|
2481|			// the string is now allocated, so set the flag
2482|			dest = buf;
2483|			header |= header_mask;
2484|
2485|			return true;
2486|		}
2487|	}
