2489|	struct gap
2490|	{
2491|		char_t* end;
2492|		size_t size;
2493|
2494|		gap(): end(NULL), size(0)
2495|		{
2496|		}
2497|
2498|		// Push new gap, move s count bytes further (skipping the gap).
2499|		// Collapse previous gap.
2500|		void push(char_t*& s, size_t count)
2501|		{
2502|			if (end) // there was a gap already; collapse it
2503|			{
2504|				// Move [old_gap_end, new_gap_start) to [old_gap_start, ...)
2505|				assert(s >= end);
2506|				memmove(end - size, end, (s - end) * sizeof(char_t));
2507|			}
2508|
2509|			s += count; // end of current gap
2510|
2511|			// "merge" two gaps
2512|			end = s;
2513|			size += count;
2514|		}
2515|
2516|		// Collapse all gaps, return past-the-end pointer
2517|		char_t* flush(char_t* s)
2518|		{
2519|			if (end)
2520|			{
2521|				// Move [old_gap_end, current_pos) to [old_gap_start, ...)
2522|				assert(s >= end);
2523|				memmove(end - size, end, (s - end) * sizeof(char_t));
2524|
2525|				return s - size;
2526|			}
2527|			else return s;
2528|		}
2529|	};
