2538|			{
2539|				unsigned int ucsc = 0;
2540|
2541|				if (stre[1] == 'x') // &#x... (hex code)
2542|				{
2543|					stre += 2;
2544|
2545|					char_t ch = *stre;
2546|
2547|					if (ch == ';') return stre;
2548|
2549|					for (;;)
2550|					{
2551|						if (static_cast<unsigned int>(ch - '0') <= 9)
2552|							ucsc = 16 * ucsc + (ch - '0');
2553|						else if (static_cast<unsigned int>((ch | ' ') - 'a') <= 5)
2554|							ucsc = 16 * ucsc + ((ch | ' ') - 'a' + 10);
