2558|							return stre;
2559|
2560|						ch = *++stre;
2561|					}
2562|
2563|					++stre;
2564|				}
2565|				else	// &#... (dec code)
2566|				{
2567|					char_t ch = *++stre;
2568|
2569|					if (ch == ';') return stre;
2570|
2571|					for (;;)
2572|					{
2573|						if (static_cast<unsigned int>(ch - '0') <= 9)
2574|							ucsc = 10 * ucsc + (ch - '0');
