2578|							return stre;
2579|
2580|						ch = *++stre;
2581|					}
2582|
2583|					++stre;
2584|				}
2585|
2586|			#ifdef PUGIXML_WCHAR_MODE
2587|				s = reinterpret_cast<char_t*>(wchar_writer::any(reinterpret_cast<wchar_writer::value_type>(s), ucsc));
2588|			#else
