2601|				{
2602|					if (*++stre == 'p' && *++stre == ';') // &amp;
2603|					{
2604|						*s++ = '&';
2605|						++stre;
2606|
2607|						g.push(s, stre - s);
2608|						return stre;
2609|					}
2610|				}
2611|				else if (*stre == 'p') // &ap
2612|				{
2613|					if (*++stre == 'o' && *++stre == 's' && *++stre == ';') // &apos;
2614|					{
2615|						*s++ = '\'';
2616|						++stre;
2617|
2618|						g.push(s, stre - s);
2619|						return stre;
2620|					}
2621|				}
2622|				break;
2623|			}
2624|
2625|			case 'g': // &g
2626|			{
2627|				if (*++stre == 't' && *++stre == ';') // &gt;
2628|				{
2629|					*s++ = '>';
2630|					++stre;
2631|
2632|					g.push(s, stre - s);
2633|					return stre;
2634|				}
2635|				break;
2636|			}
2637|
2638|			case 'l': // &l
2639|			{
2640|				if (*++stre == 't' && *++stre == ';') // &lt;
2641|				{
2642|					*s++ = '<';
2643|					++stre;
2644|
2645|					g.push(s, stre - s);
2646|					return stre;
2647|				}
2648|				break;
2649|			}
2650|
2651|			case 'q': // &q
2652|			{
2653|				if (*++stre == 'u' && *++stre == 'o' && *++stre == 't' && *++stre == ';') // &quot;
2654|				{
2655|					*s++ = '"';
2656|					++stre;
2657|
2658|					g.push(s, stre - s);
2659|					return stre;
2660|				}
2661|				break;
2662|			}
2663|
2664|			default:
