3007|		// DOCTYPE consists of nested sections of the following possible types:
3008|		// <!-- ... -->, <? ... ?>, "...", '...'
3009|		// <![...]]>
3010|		// <!...>
3011|		// First group can not contain nested groups
3012|		// Second group can contain nested groups of the same type
3013|		// Third group can contain all other groups
3014|		char_t* parse_doctype_primitive(char_t* s)
3015|		{
3016|			if (*s == '"' || *s == '\'')
3017|			{
3018|				// quoted string
3019|				char_t ch = *s++;
3020|				PUGI_IMPL_SCANFOR(*s == ch);
3021|				if (!*s) PUGI_IMPL_THROW_ERROR(status_bad_doctype, s);
3022|
3023|				s++;
3024|			}
3025|			else if (s[0] == '<' && s[1] == '?')
3026|			{
3027|				// <? ... ?>
3028|				s += 2;
3029|				PUGI_IMPL_SCANFOR(s[0] == '?' && s[1] == '>'); // no need for ENDSWITH because ?> can't terminate proper doctype
3030|				if (!*s) PUGI_IMPL_THROW_ERROR(status_bad_doctype, s);
3031|
3032|				s += 2;
3033|			}
3034|			else if (s[0] == '<' && s[1] == '!' && s[2] == '-' && s[3] == '-')
3035|			{
3036|				s += 4;
3037|				PUGI_IMPL_SCANFOR(s[0] == '-' && s[1] == '-' && s[2] == '>'); // no need for ENDSWITH because --> can't terminate proper doctype
3038|				if (!*s) PUGI_IMPL_THROW_ERROR(status_bad_doctype, s);
3039|
3040|				s += 3;
3041|			}
3042|			else PUGI_IMPL_THROW_ERROR(status_bad_doctype, s);
3043|
3044|			return s;
3045|		}
