3047|		char_t* parse_doctype_ignore(char_t* s)
3048|		{
3049|			size_t depth = 0;
3050|
3051|			assert(s[0] == '<' && s[1] == '!' && s[2] == '[');
3052|			s += 3;
3053|
3054|			while (*s)
3055|			{
3056|				if (s[0] == '<' && s[1] == '!' && s[2] == '[')
3057|				{
3058|					// nested ignore section
3059|					s += 3;
3060|					depth++;
3061|				}
3062|				else if (s[0] == ']' && s[1] == ']' && s[2] == '>')
3063|				{
3064|					// ignore section end
3065|					s += 3;
3066|
3067|					if (depth == 0)
3068|						return s;
3069|
3070|					depth--;
3071|				}
3072|				else s++;
3073|			}
3074|
3075|			PUGI_IMPL_THROW_ERROR(status_bad_doctype, s);
3076|		}
