3081|
3082|			assert((s[0] == '<' || s[0] == 0) && s[1] == '!');
3083|			s += 2;
3084|
3085|			while (*s)
3086|			{
3087|				if (s[0] == '<' && s[1] == '!' && s[2] != '-')
3088|				{
3089|					if (s[2] == '[')
3090|					{
3091|						// ignore
3092|						s = parse_doctype_ignore(s);
3093|						if (!s) return s;
3094|					}
3095|					else
3096|					{
3097|						// some control group
3098|						s += 2;
3099|						depth++;
3100|					}
3101|				}
3102|				else if (s[0] == '<' || s[0] == '"' || s[0] == '\'')
