3813|		void flush(const char_t* data, size_t size)
3814|		{
3815|			if (size == 0) return;
3816|
3817|			// fast path, just write data
3818|			if (encoding == get_write_native_encoding())
3819|				writer.write(data, size * sizeof(char_t));
3820|			else
3821|			{
3822|				// convert chunk
3823|				size_t result = convert_buffer_output(scratch.data_char, scratch.data_u8, scratch.data_u16, scratch.data_u32, data, size, encoding);
3824|				assert(result <= sizeof(scratch));
3825|
3826|				// write data
3827|				writer.write(scratch.data_u8, result);
