3831|		void write_direct(const char_t* data, size_t length)
3832|		{
3833|			// flush the remaining buffer contents
3834|			flush();
3835|
3836|			// handle large chunks
3837|			if (length > bufcapacity)
3838|			{
3839|				if (encoding == get_write_native_encoding())
3840|				{
3841|					// fast path, can just write data chunk
3842|					writer.write(data, length * sizeof(char_t));
3843|					return;
3844|				}
3845|
3846|				// need to convert in suitable chunks
3847|				while (length > bufcapacity)
3848|				{
