4009|	PUGI_IMPL_FN void text_output_escaped(xml_buffered_writer& writer, const char_t* s, chartypex_t type, unsigned int flags)
4010|	{
4011|		while (*s)
4012|		{
4013|			const char_t* prev = s;
4014|
4015|			// While *s is a usual symbol
4016|			PUGI_IMPL_SCANWHILE_UNROLL(!PUGI_IMPL_IS_CHARTYPEX(ss, type));
4017|
4018|			writer.write_buffer(prev, static_cast<size_t>(s - prev));
4019|
4020|			switch (*s)
4021|			{
4022|				case 0: break;
4023|				case '&':
4024|					writer.write('&', 'a', 'm', 'p', ';');
4025|					++s;
4026|					break;
4027|				case '<':
4028|					writer.write('&', 'l', 't', ';');
4029|					++s;
4030|					break;
4031|				case '>':
4032|					writer.write('&', 'g', 't', ';');
4033|					++s;
4034|					break;
4035|				case '"':
4036|					if (flags & format_attribute_single_quote)
4037|						writer.write('"');
4038|					else
4039|						writer.write('&', 'q', 'u', 'o', 't', ';');
4040|					++s;
4041|					break;
4042|				case '\'':
4043|					if (flags & format_attribute_single_quote)
4044|						writer.write('&', 'a', 'p', 'o', 's', ';');
4045|					else
4046|						writer.write('\'');
4047|					++s;
4048|					break;
4049|				default: // s is not a usual symbol
4050|				{
4051|					unsigned int ch = static_cast<unsigned int>(*s++);
4052|					assert(ch < 32);
4053|
4054|					if (!(flags & format_skip_control_chars))
4055|						writer.write('&', '#', static_cast<char_t>((ch / 10) + '0'), static_cast<char_t>((ch % 10) + '0'), ';');
4056|				}
4057|			}
4058|		}
4059|	}
