4069|	PUGI_IMPL_FN void text_output_cdata(xml_buffered_writer& writer, const char_t* s)
4070|	{
4071|		do
4072|		{
4073|			writer.write('<', '!', '[', 'C', 'D');
4074|			writer.write('A', 'T', 'A', '[');
4075|
4076|			const char_t* prev = s;
4077|
4078|			// look for ]]> sequence - we can't output it as is since it terminates CDATA
4079|			while (*s && !(s[0] == ']' && s[1] == ']' && s[2] == '>')) ++s;
4080|
4081|			// skip ]] if we stopped at ]]>, > will go to the next CDATA section
4082|			if (*s) s += 2;
4083|
4084|			writer.write_buffer(prev, static_cast<size_t>(s - prev));
4085|
4086|			writer.write(']', ']', '>');
4087|		}
4088|		while (*s);
4089|	}
