4091|	PUGI_IMPL_FN void text_output_indent(xml_buffered_writer& writer, const char_t* indent, size_t indent_length, unsigned int depth)
4092|	{
4093|		switch (indent_length)
4094|		{
4095|		case 1:
4096|		{
4097|			for (unsigned int i = 0; i < depth; ++i)
4098|				writer.write(indent[0]);
4099|			break;
4100|		}
4101|
4102|		case 2:
4103|		{
4104|			for (unsigned int i = 0; i < depth; ++i)
4105|				writer.write(indent[0], indent[1]);
4106|			break;
4107|		}
4108|
4109|		case 3:
4110|		{
4111|			for (unsigned int i = 0; i < depth; ++i)
4112|				writer.write(indent[0], indent[1], indent[2]);
4113|			break;
4114|		}
4115|
4116|		case 4:
4117|		{
4118|			for (unsigned int i = 0; i < depth; ++i)
4119|				writer.write(indent[0], indent[1], indent[2], indent[3]);
4120|			break;
4121|		}
4122|
4123|		default:
4124|		{
