4131|	PUGI_IMPL_FN void node_output_comment(xml_buffered_writer& writer, const char_t* s)
4132|	{
4133|		writer.write('<', '!', '-', '-');
4134|
4135|		while (*s)
4136|		{
4137|			const char_t* prev = s;
4138|
4139|			// look for -\0 or -- sequence - we can't output it since -- is illegal in comment body
4140|			while (*s && !(s[0] == '-' && (s[1] == '-' || s[1] == 0))) ++s;
4141|
4142|			writer.write_buffer(prev, static_cast<size_t>(s - prev));
4143|
4144|			if (*s)
4145|			{
4146|				assert(*s == '-');
4147|
4148|				writer.write('-', ' ');
4149|				++s;
4150|			}
4151|		}
4152|
4153|		writer.write('-', '-', '>');
4154|	}
