4156|	PUGI_IMPL_FN void node_output_pi_value(xml_buffered_writer& writer, const char_t* s)
4157|	{
4158|		while (*s)
4159|		{
4160|			const char_t* prev = s;
4161|
4162|			// look for ?> sequence - we can't output it since ?> terminates PI
4163|			while (*s && !(s[0] == '?' && s[1] == '>')) ++s;
4164|
4165|			writer.write_buffer(prev, static_cast<size_t>(s - prev));
4166|
4167|			if (*s)
4168|			{
4169|				assert(s[0] == '?' && s[1] == '>');
4170|
4171|				writer.write('?', ' ', '>');
4172|				s += 2;
4173|			}
4174|		}
