4240|
4241|					writer.write('/', '>');
4242|
4243|					return false;
4244|				}
4245|			}
4246|			else
4247|			{
4248|				writer.write('>');
4249|
4250|				return true;
4251|			}
4252|		}
4253|		else
4254|		{
4255|			writer.write('>');
4256|
4257|			text_output(writer, node->value, ctx_special_pcdata, flags);
4258|
4259|			if (!node->first_child)
4260|			{
4261|				writer.write('<', '/');
4262|				writer.write_string(name);
4263|				writer.write('>');
4264|
4265|				return false;
4266|			}
4267|			else
4268|			{
4269|				return true;
4270|			}
4271|		}
