4284|	PUGI_IMPL_FN void node_output_simple(xml_buffered_writer& writer, xml_node_struct* node, unsigned int flags)
4285|	{
4286|		const char_t* default_name = PUGIXML_TEXT(":anonymous");
4287|
4288|		switch (PUGI_IMPL_NODETYPE(node))
4289|		{
4290|			case node_pcdata:
