4293|
4294|			case node_cdata:
4295|				text_output_cdata(writer, node->value ? node->value + 0 : PUGIXML_TEXT(""));
4296|				break;
4297|
4298|			case node_comment:
4299|				node_output_comment(writer, node->value ? node->value + 0 : PUGIXML_TEXT(""));
4300|				break;
4301|
4302|			case node_pi:
4303|				writer.write('<', '?');
