4346|	PUGI_IMPL_FN void node_output(xml_buffered_writer& writer, xml_node_struct* root, const char_t* indent, unsigned int flags, unsigned int depth)
4347|	{
4348|		size_t indent_length = ((flags & (format_indent | format_indent_attributes)) && (flags & format_raw) == 0) ? strlength(indent) : 0;
4349|		unsigned int indent_flags = indent_indent;
4350|
4351|		xml_node_struct* node = root;
4352|
4353|		do
4354|		{
4355|			assert(node);
4356|
4357|			// begin writing current node
4358|			if (PUGI_IMPL_NODETYPE(node) == node_pcdata || PUGI_IMPL_NODETYPE(node) == node_cdata)
4359|			{
4360|				node_output_simple(writer, node, flags);
4361|
4362|				indent_flags = 0;
4363|			}
4364|			else
4365|			{
4366|				if ((indent_flags & indent_newline) && (flags & format_raw) == 0)
4367|					writer.write('\n');
4368|
4369|				if ((indent_flags & indent_indent) && indent_length)
4370|					text_output_indent(writer, indent, indent_length, depth);
4371|
4372|				if (PUGI_IMPL_NODETYPE(node) == node_element)
4373|				{
4374|					indent_flags = indent_newline | indent_indent;
4375|
4376|					if (node_output_start(writer, node, indent, indent_length, flags, depth))
4377|					{
4378|						// element nodes can have value if parse_embed_pcdata was used
4379|						if (node->value)
4380|							indent_flags = 0;
4381|
4382|						node = node->first_child;
4383|						depth++;
4384|						continue;
4385|					}
4386|				}
4387|				else if (PUGI_IMPL_NODETYPE(node) == node_document)
4388|				{
4389|					indent_flags = indent_indent;
4390|
4391|					if (node->first_child)
4392|					{
4393|						node = node->first_child;
4394|						continue;
4395|					}
4396|				}
4397|				else
4398|				{
4399|					node_output_simple(writer, node, flags);
4400|
4401|					indent_flags = indent_newline | indent_indent;
4402|				}
4403|			}
4404|
4405|			// continue to the next node
4406|			while (node != root)
4407|			{
4408|				if (node->next_sibling)
4409|				{
4410|					node = node->next_sibling;
4411|					break;
4412|				}
4413|
4414|				node = node->parent;
4415|
4416|				// write closing node
4417|				if (PUGI_IMPL_NODETYPE(node) == node_element)
4418|				{
4419|					depth--;
4420|
4421|					if ((indent_flags & indent_newline) && (flags & format_raw) == 0)
4422|						writer.write('\n');
4423|
4424|					if ((indent_flags & indent_indent) && indent_length)
4425|						text_output_indent(writer, indent, indent_length, depth);
4426|
4427|					node_output_end(writer, node);
4428|
4429|					indent_flags = indent_newline | indent_indent;
4430|				}
4431|			}
4432|		}
4433|		while (node != root);
4434|
4435|		if ((indent_flags & indent_newline) && (flags & format_raw) == 0)
4436|			writer.write('\n');
4437|	}
