4478|		if (!allow_insert_child(parent.type(), child.type()))
4479|			return false;
4480|
4481|		// check that node is not moved between documents
4482|		if (parent.root() != child.root())
4483|			return false;
4484|
4485|		// check that new parent is not in the child subtree
4486|		xml_node cur = parent;
4487|
4488|		while (cur)
4489|		{
4490|			if (cur == child)
4491|				return false;
4492|
4493|			cur = cur.parent();
4494|		}
4495|
4496|		return true;
4497|	}
