4539|	PUGI_IMPL_FN void node_copy_tree(xml_node_struct* dn, xml_node_struct* sn)
4540|	{
4541|		xml_allocator& alloc = get_allocator(dn);
4542|		xml_allocator* shared_alloc = (&alloc == &get_allocator(sn)) ? &alloc : NULL;
4543|
4544|		node_copy_contents(dn, sn, shared_alloc);
4545|
4546|		xml_node_struct* dit = dn;
4547|		xml_node_struct* sit = sn->first_child;
4548|
4549|		while (sit && sit != sn)
4550|		{
4551|			// loop invariant: dit is inside the subtree rooted at dn
4552|			assert(dit);
4553|
4554|			// when a tree is copied into one of the descendants, we need to skip that subtree to avoid an infinite loop
4555|			if (sit != dn)
4556|			{
4557|				xml_node_struct* copy = append_new_node(dit, alloc, PUGI_IMPL_NODETYPE(sit));
4558|
4559|				if (copy)
4560|				{
4561|					node_copy_contents(copy, sit, shared_alloc);
4562|
4563|					if (sit->first_child)
4564|					{
4565|						dit = copy;
4566|						sit = sit->first_child;
4567|						continue;
4568|					}
4569|				}
4570|			}
4571|
4572|			// continue to the next node
4573|			do
4574|			{
4575|				if (sit->next_sibling)
4576|				{
4577|					sit = sit->next_sibling;
4578|					break;
4579|				}
4580|
4581|				sit = sit->parent;
4582|				dit = dit->parent;
4583|
4584|				// loop invariant: dit is inside the subtree rooted at dn while sit is inside sn
4585|				assert(sit == sn || dit);
4586|			}
4587|			while (sit != sn);
4588|		}
4589|
4590|		assert(!sit || dit == dn->parent);
4591|	}
