4610|	template <typename U> PUGI_IMPL_FN PUGI_IMPL_UNSIGNED_OVERFLOW U string_to_integer(const char_t* value, U minv, U maxv)
4611|	{
4612|		U result = 0;
4613|		const char_t* s = value;
4614|
4615|		while (PUGI_IMPL_IS_CHARTYPE(*s, ct_space))
4616|			s++;
4617|
4618|		bool negative = (*s == '-');
4619|
4620|		s += (*s == '+' || *s == '-');
4621|
4622|		bool overflow = false;
4623|
4624|		if (s[0] == '0' && (s[1] | ' ') == 'x')
4625|		{
4626|			s += 2;
4627|
4628|			// since overflow detection relies on length of the sequence skip leading zeros
4629|			while (*s == '0')
4630|				s++;
4631|
4632|			const char_t* start = s;
4633|
4634|			for (;;)
4635|			{
4636|				if (static_cast<unsigned>(*s - '0') < 10)
4637|					result = result * 16 + (*s - '0');
4638|				else if (static_cast<unsigned>((*s | ' ') - 'a') < 6)
4639|					result = result * 16 + ((*s | ' ') - 'a' + 10);
4640|				else
4641|					break;
4642|
4643|				s++;
4644|			}
4645|
4646|			size_t digits = static_cast<size_t>(s - start);
4647|
4648|			overflow = digits > sizeof(U) * 2;
4649|		}
4650|		else
4651|		{
4652|			// since overflow detection relies on length of the sequence skip leading zeros
4653|			while (*s == '0')
4654|				s++;
4655|
4656|			const char_t* start = s;
4657|
4658|			for (;;)
4659|			{
4660|				if (static_cast<unsigned>(*s - '0') < 10)
4661|					result = result * 10 + (*s - '0');
4662|				else
4663|					break;
4664|
4665|				s++;
4666|			}
4667|
4668|			size_t digits = static_cast<size_t>(s - start);
4669|
4670|			PUGI_IMPL_STATIC_ASSERT(sizeof(U) == 8 || sizeof(U) == 4 || sizeof(U) == 2);
4671|
4672|			const size_t max_digits10 = sizeof(U) == 8 ? 20 : sizeof(U) == 4 ? 10 : 5;
4673|			const char_t max_lead = sizeof(U) == 8 ? '1' : sizeof(U) == 4 ? '4' : '6';
4674|			const size_t high_bit = sizeof(U) * 8 - 1;
4675|
4676|			overflow = digits >= max_digits10 && !(digits == max_digits10 && (*start < max_lead || (*start == max_lead && result >> high_bit)));
4677|		}
4678|
4679|		if (negative)
4680|		{
4681|			// Workaround for crayc++ CC-3059: Expected no overflow in routine.
4682|		#ifdef _CRAYC
4683|			return (overflow || result > ~minv + 1) ? minv : ~result + 1;
4684|		#else
4685|			return (overflow || result > 0 - minv) ? minv : 0 - result;
4686|		#endif
4687|		}
4688|		else
4689|			return (overflow || result > maxv) ? maxv : result;
4690|	}
