4901|	// we need to get length of entire file to load it in memory; the only (relatively) sane way to do it is via seek/tell trick
4902|	PUGI_IMPL_FN xml_parse_status get_file_size(FILE* file, size_t& out_result)
4903|	{
4904|	#if defined(__linux__) || defined(__APPLE__)
4905|		// this simultaneously retrieves the file size and file mode (to guard against loading non-files)
4906|		struct stat st;
4907|		if (fstat(fileno(file), &st) != 0) return status_io_error;
4908|
4909|		// anything that's not a regular file doesn't have a coherent length
4910|		if (!S_ISREG(st.st_mode)) return status_io_error;
4911|
4912|		xml_parse_status status = convert_file_size(st.st_size, out_result);
4913|	#elif defined(PUGI_IMPL_MSVC_CRT_VERSION) && PUGI_IMPL_MSVC_CRT_VERSION >= 1400
4914|		// there are 64-bit versions of fseek/ftell, let's use them
4915|		_fseeki64(file, 0, SEEK_END);
4916|		__int64 length = _ftelli64(file);
4917|		_fseeki64(file, 0, SEEK_SET);
4918|
4919|		xml_parse_status status = convert_file_size(length, out_result);
4920|	#elif defined(__MINGW32__) && !defined(__NO_MINGW_LFS) && (!defined(__STRICT_ANSI__) || defined(__MINGW64_VERSION_MAJOR))
4921|		// there are 64-bit versions of fseek/ftell, let's use them
4922|		fseeko64(file, 0, SEEK_END);
4923|		off64_t length = ftello64(file);
4924|		fseeko64(file, 0, SEEK_SET);
4925|
4926|		xml_parse_status status = convert_file_size(length, out_result);
4927|	#else
4928|		// if this is a 32-bit OS, long is enough; if this is a unix system, long is 64-bit, which is enough; otherwise we can't do anything anyway.
4929|		fseek(file, 0, SEEK_END);
4930|		long length = ftell(file);
4931|		fseek(file, 0, SEEK_SET);
4932|
4933|		xml_parse_status status = convert_file_size(length, out_result);
4934|	#endif
4935|
4936|		return status;
4937|	}
