4951|			return (length + 1) * sizeof(char_t);
4952|		}
4953|	#else
4954|		if (encoding == encoding_utf8)
4955|		{
4956|			static_cast<char*>(buffer)[size] = 0;
4957|			return size + 1;
4958|		}
4959|	#endif
