4964|	PUGI_IMPL_FN xml_parse_result load_file_impl(xml_document_struct* doc, FILE* file, unsigned int options, xml_encoding encoding, char_t** out_buffer)
4965|	{
4966|		if (!file) return make_parse_result(status_file_not_found);
4967|
4968|		// get file size (can result in I/O errors)
4969|		size_t size = 0;
4970|		xml_parse_status size_status = get_file_size(file, size);
4971|		if (size_status != status_ok) return make_parse_result(size_status);
4972|
4973|		size_t max_suffix_size = sizeof(char_t);
4974|		if (static_cast<size_t>(-1) - max_suffix_size < size) return make_parse_result(status_out_of_memory);
4975|
4976|		// allocate buffer for the whole file
4977|		char* contents = static_cast<char*>(xml_memory::allocate(size + max_suffix_size));
4978|		if (!contents) return make_parse_result(status_out_of_memory);
4979|
4980|		// read file in memory
4981|		size_t read_size = fread(contents, 1, size, file);
4982|
4983|		if (read_size != size)
4984|		{
4985|			xml_memory::deallocate(contents);
4986|			return make_parse_result(status_io_error);
4987|		}
4988|
4989|		xml_encoding real_encoding = get_buffer_encoding(encoding, contents, size);
4990|
4991|		return load_buffer_impl(doc, doc, contents, zero_terminate_buffer(contents, size, real_encoding), options, real_encoding, true, true, out_buffer);
4992|	}
