5043|			// allocate new chunk
5044|			xml_stream_chunk<T>* chunk = xml_stream_chunk<T>::create();
5045|			if (!chunk) return status_out_of_memory;
5046|
5047|			// append chunk to list
5048|			if (last) last = last->next = chunk;
5049|			else chunks.data = last = chunk;
5050|
5051|			// read data to chunk
5052|			stream.read(chunk->data, static_cast<std::streamsize>(sizeof(chunk->data) / sizeof(T)));
5053|			chunk->size = static_cast<size_t>(stream.gcount()) * sizeof(T);
5054|
5055|			// read may set failbit | eofbit in case gcount() is less than read length, so check for other I/O errors
5056|			if (stream.bad() || (!stream.eof() && stream.fail())) return status_io_error;
5057|
5058|			// guard against huge files (chunk size is small enough to make this overflow check work)
5059|			if (total + chunk->size < total) return status_out_of_memory;
5060|			total += chunk->size;
5061|		}
5062|
5063|		size_t max_suffix_size = sizeof(char_t);
5064|		if (static_cast<size_t>(-1) - max_suffix_size < total) return status_out_of_memory;
5065|
5066|		// copy chunk list to a contiguous buffer
5067|		char* buffer = static_cast<char*>(xml_memory::allocate(total + max_suffix_size));
5068|		if (!buffer) return status_out_of_memory;
5069|
5070|		char* write = buffer;
5071|
5072|		for (xml_stream_chunk<T>* chunk = chunks.data; chunk; chunk = chunk->next)
5073|		{
5074|			assert(write + chunk->size <= buffer + total);
5075|			memcpy(write, chunk->data, chunk->size);
5076|			write += chunk->size;
5077|		}
5078|
5079|		assert(write == buffer + total);
5080|
5081|		// return buffer
5082|		*out_buffer = buffer;
5083|		*out_size = total;
