5088|	template <typename T> PUGI_IMPL_FN xml_parse_status load_stream_data_seek(std::basic_istream<T>& stream, void** out_buffer, size_t* out_size)
5089|	{
5090|		// get length of remaining data in stream
5091|		typename std::basic_istream<T>::pos_type pos = stream.tellg();
5092|		stream.seekg(0, std::ios::end);
5093|		std::streamoff length = stream.tellg() - pos;
5094|		stream.seekg(pos);
5095|
5096|		if (stream.fail() || pos < 0) return status_io_error;
5097|
5098|		// guard against huge files
5099|		size_t read_length = static_cast<size_t>(length);
5100|
5101|		if (static_cast<std::streamsize>(read_length) != length || length < 0) return status_out_of_memory;
5102|
5103|		size_t max_suffix_size = sizeof(char_t);
5104|		if ((static_cast<size_t>(-1) - max_suffix_size) / sizeof(T) < read_length) return status_out_of_memory;
5105|
5106|		// read stream data into memory (guard against stream exceptions with buffer holder)
5107|		auto_deleter<void> buffer(xml_memory::allocate(read_length * sizeof(T) + max_suffix_size), xml_memory::deallocate);
5108|		if (!buffer.data) return status_out_of_memory;
5109|
5110|		stream.read(static_cast<T*>(buffer.data), static_cast<std::streamsize>(read_length));
5111|
5112|		// read may set failbit | eofbit in case gcount() is less than read_length (i.e. line ending conversion), so check for other I/O errors
5113|		if (stream.bad() || (!stream.eof() && stream.fail())) return status_io_error;
5114|
5115|		// return buffer
5116|		size_t actual_length = static_cast<size_t>(stream.gcount());
5117|		assert(actual_length <= read_length);
5118|
5119|		*out_buffer = buffer.release();
5120|		*out_size = actual_length * sizeof(T);
5121|
5122|		return status_ok;
5123|	}
