5125|	template <typename T> PUGI_IMPL_FN xml_parse_result load_stream_impl(xml_document_struct* doc, std::basic_istream<T>& stream, unsigned int options, xml_encoding encoding, char_t** out_buffer)
5126|	{
5127|		void* buffer = NULL;
5128|		size_t size = 0;
5129|		xml_parse_status status = status_ok;
5130|
5131|		// if stream has an error bit set, bail out (otherwise tellg() can fail and we'll clear error bits)
5132|		if (stream.fail()) return make_parse_result(status_io_error);
5133|
5134|		// load stream to memory (using seek-based implementation if possible, since it's faster and takes less memory)
5135|		if (stream.tellg() < 0)
