5139|		}
5140|		else
5141|			status = load_stream_data_seek(stream, &buffer, &size);
5142|
5143|		if (status != status_ok) return make_parse_result(status);
5144|
5145|		xml_encoding real_encoding = get_buffer_encoding(encoding, buffer, size);
5146|
5147|		return load_buffer_impl(doc, doc, buffer, zero_terminate_buffer(buffer, size, real_encoding), options, real_encoding, true, true, out_buffer);
