5902|	PUGI_IMPL_FN xml_attribute xml_node::attribute(const char_t* name_, xml_attribute& hint_) const
5903|	{
5904|		xml_attribute_struct* hint = hint_._attr;
5905|
5906|		// if hint is not an attribute of node, behavior is not defined
5907|		assert(!hint || (_root && impl::is_attribute_of(hint, _root)));
5908|
5909|		if (!_root) return xml_attribute();
5910|
5911|		// optimistically search from hint up until the end
5912|		for (xml_attribute_struct* i = hint; i; i = i->next_attribute)
5913|		{
5914|			const char_t* iname = i->name;
5915|			if (iname && impl::strequal(name_, iname))
5916|			{
5917|				// update hint to maximize efficiency of searching for consecutive attributes
5918|				hint_._attr = i->next_attribute;
5919|
5920|				return xml_attribute(i);
5921|			}
5922|		}
5923|
5924|		// wrap around and search from the first attribute until the hint
5925|		// 'j' null pointer check is technically redundant, but it prevents a crash in case the assertion above fails
5926|		for (xml_attribute_struct* j = _root->first_attribute; j && j != hint; j = j->next_attribute)
5927|		{
5928|			const char_t* jname = j->name;
5929|			if (jname && impl::strequal(name_, jname))
5930|			{
5931|				// update hint to maximize efficiency of searching for consecutive attributes
5932|				hint_._attr = j->next_attribute;
5933|
5934|				return xml_attribute(j);
5935|			}
5936|		}
5937|
5938|		return xml_attribute();
5939|	}
