6712|		// get document node
6713|		impl::xml_document_struct* doc = &impl::get_document(_root);
6714|
6715|		// disable document_buffer_order optimization since in a document with multiple buffers comparing buffer pointers does not make sense
6716|		doc->header |= impl::xml_memory_page_contents_shared_mask;
6717|
6718|		// get extra buffer element (we'll store the document fragment buffer there so that we can deallocate it later)
6719|		impl::xml_memory_page* page = NULL;
6720|		impl::xml_extra_buffer* extra = static_cast<impl::xml_extra_buffer*>(doc->allocate_memory(sizeof(impl::xml_extra_buffer) + sizeof(void*), page));
6721|		(void)page;
6722|
6723|		if (!extra) return impl::make_parse_result(status_out_of_memory);
6724|
6725|	#ifdef PUGIXML_COMPACT
6726|		// align the memory block to a pointer boundary; this is required for compact mode where memory allocations are only 4b aligned
6727|		// note that this requires up to sizeof(void*)-1 additional memory, which the allocation above takes into account
6728|		extra = reinterpret_cast<impl::xml_extra_buffer*>((reinterpret_cast<uintptr_t>(extra) + (sizeof(void*) - 1)) & ~(sizeof(void*) - 1));
6729|	#endif
6730|
6731|		// add extra buffer to the list
6732|		extra->buffer = NULL;
6733|		extra->next = doc->extra_buffers;
6734|		doc->extra_buffers = extra;
6735|
6736|		// name of the root has to be NULL before parsing - otherwise closing node mismatches will not be detected at the top level
6737|		impl::name_null_sentry sentry(_root);
6738|
6739|		return impl::load_buffer_impl(doc, _root, const_cast<void*>(contents), size, options, encoding, false, false, &extra->buffer);
6740|	}
