6742|	PUGI_IMPL_FN xml_node xml_node::find_child_by_attribute(const char_t* name_, const char_t* attr_name, const char_t* attr_value) const
6743|	{
6744|		if (!_root) return xml_node();
6745|
6746|		for (xml_node_struct* i = _root->first_child; i; i = i->next_sibling)
6747|		{
6748|			const char_t* iname = i->name;
6749|			if (iname && impl::strequal(name_, iname))
6750|			{
6751|				for (xml_attribute_struct* a = i->first_attribute; a; a = a->next_attribute)
6752|				{
6753|					const char_t* aname = a->name;
6754|					if (aname && impl::strequal(attr_name, aname))
6755|					{
6756|						const char_t* avalue = a->value;
6757|						if (impl::strequal(attr_value, avalue ? avalue : PUGIXML_TEXT("")))
6758|							return xml_node(i);
6759|					}
6760|				}
6761|			}
6762|		}
6763|
6764|		return xml_node();
