6786|#ifndef PUGIXML_NO_STL
6787|	PUGI_IMPL_FN string_t xml_node::path(char_t delimiter) const
6788|	{
6789|		if (!_root) return string_t();
6790|
6791|		size_t offset = 0;
6792|
6793|		for (xml_node_struct* i = _root; i; i = i->parent)
6794|		{
6795|			const char_t* iname = i->name;
6796|			offset += (i != _root);
6797|			offset += iname ? impl::strlength(iname) : 0;
6798|		}
6799|
6800|		string_t result;
6801|		result.resize(offset);
6802|
6803|		for (xml_node_struct* j = _root; j; j = j->parent)
6804|		{
6805|			if (j != _root)
6806|				result[--offset] = delimiter;
6807|
6808|			const char_t* jname = j->name;
6809|			if (jname)
6810|			{
6811|				size_t length = impl::strlength(jname);
6812|
6813|				offset -= length;
6814|				memcpy(&result[offset], jname, length * sizeof(char_t));
6815|			}
6816|		}
6817|
6818|		assert(offset == 0);
6819|
6820|		return result;
6821|	}
6822|#endif
6823|
6824|	PUGI_IMPL_FN xml_node xml_node::first_element_by_path(const char_t* path_, char_t delimiter) const
6825|	{
6826|		assert(delimiter != 0);
6827|
6828|		xml_node context = path_[0] == delimiter ? root() : *this;
6829|
6830|		if (!context._root) return xml_node();
6831|
6832|		const char_t* path_segment = path_;
6833|
6834|		while (*path_segment == delimiter) ++path_segment;
6835|
6836|		const char_t* path_segment_end = path_segment;
6837|
6838|		while (*path_segment_end && *path_segment_end != delimiter) ++path_segment_end;
6839|
6840|		if (path_segment == path_segment_end) return context;
6841|
6842|		const char_t* next_segment = path_segment_end;
6843|
6844|		while (*next_segment == delimiter) ++next_segment;
6845|
6846|		if (*path_segment == '.' && path_segment + 1 == path_segment_end)
6847|			return context.first_element_by_path(next_segment, delimiter);
6848|		else if (*path_segment == '.' && *(path_segment+1) == '.' && path_segment + 2 == path_segment_end)
6849|			return context.parent().first_element_by_path(next_segment, delimiter);
6850|		else
6851|		{
6852|			for (xml_node_struct* j = context._root->first_child; j; j = j->next_sibling)
6853|			{
6854|				const char_t* jname = j->name;
6855|				if (jname && impl::strequalrange(jname, path_segment, static_cast<size_t>(path_segment_end - path_segment)))
6856|				{
6857|					xml_node subsearch = xml_node(j).first_element_by_path(next_segment, delimiter);
6858|
6859|					if (subsearch) return subsearch;
6860|				}
6861|			}
6862|
6863|			return xml_node();
6864|		}
6865|	}
