6867|	PUGI_IMPL_FN bool xml_node::traverse(xml_tree_walker& walker)
6868|	{
6869|		walker._depth = -1;
6870|
6871|		xml_node arg_begin(_root);
6872|		if (!walker.begin(arg_begin)) return false;
6873|
6874|		xml_node_struct* cur = _root ? _root->first_child + 0 : NULL;
6875|
6876|		if (cur)
6877|		{
6878|			++walker._depth;
6879|
6880|			do
6881|			{
6882|				xml_node arg_for_each(cur);
6883|				if (!walker.for_each(arg_for_each))
6884|					return false;
6885|
6886|				if (cur->first_child)
6887|				{
6888|					++walker._depth;
6889|					cur = cur->first_child;
6890|				}
6891|				else if (cur->next_sibling)
6892|					cur = cur->next_sibling;
6893|				else
6894|				{
6895|					while (!cur->next_sibling && cur != _root && cur->parent)
6896|					{
6897|						--walker._depth;
6898|						cur = cur->parent;
6899|					}
6900|
6901|					if (cur != _root)
6902|						cur = cur->next_sibling;
6903|				}
6904|			}
6905|			while (cur && cur != _root);
6906|		}
6907|
6908|		assert(walker._depth == -1);
6909|
6910|		xml_node arg_end(_root);
6911|		return walker.end(arg_end);
6912|	}
