6951|	PUGI_IMPL_FN ptrdiff_t xml_node::offset_debug() const
6952|	{
6953|		if (!_root) return -1;
6954|
6955|		impl::xml_document_struct& doc = impl::get_document(_root);
6956|
6957|		// we can determine the offset reliably only if there is exactly once parse buffer
6958|		if (!doc.buffer || doc.extra_buffers) return -1;
6959|
6960|		switch (type())
6961|		{
6962|		case node_document:
6963|			return 0;
6964|
6965|		case node_element:
6966|		case node_declaration:
6967|		case node_pi:
6968|			return _root->name && (_root->header & impl::xml_memory_page_name_allocated_or_shared_mask) == 0 ? _root->name - doc.buffer : -1;
6969|
6970|		case node_pcdata:
6971|		case node_cdata:
6972|		case node_comment:
6973|		case node_doctype:
6974|			return _root->value && (_root->header & impl::xml_memory_page_value_allocated_or_shared_mask) == 0 ? _root->value - doc.buffer : -1;
6975|
6976|		default:
6977|			assert(false && "Invalid node type"); // unreachable
6978|			return -1;
6979|		}
6980|	}
