7593|	PUGI_IMPL_FN void xml_document::_create()
7594|	{
7595|		assert(!_root);
7596|
7597|	#ifdef PUGIXML_COMPACT
7598|		// space for page marker for the first page (uint32_t), rounded up to pointer size; assumes pointers are at least 32-bit
7599|		const size_t page_offset = sizeof(void*);
7600|	#else
7601|		const size_t page_offset = 0;
7602|	#endif
7603|
7604|		// initialize sentinel page
7605|		PUGI_IMPL_STATIC_ASSERT(sizeof(impl::xml_memory_page) + sizeof(impl::xml_document_struct) + page_offset <= sizeof(_memory));
7606|
7607|		// prepare page structure
7608|		impl::xml_memory_page* page = impl::xml_memory_page::construct(_memory);
7609|		assert(page);
7610|
7611|		page->busy_size = impl::xml_memory_page_size;
7612|
7613|		// setup first page marker
7614|	#ifdef PUGIXML_COMPACT
7615|		// round-trip through void* to avoid 'cast increases required alignment of target type' warning
7616|		page->compact_page_marker = reinterpret_cast<uint32_t*>(static_cast<void*>(reinterpret_cast<char*>(page) + sizeof(impl::xml_memory_page)));
7617|		*page->compact_page_marker = sizeof(impl::xml_memory_page);
7618|	#endif
7619|
7620|		// allocate new root
7621|		_root = new (reinterpret_cast<char*>(page) + sizeof(impl::xml_memory_page) + page_offset) impl::xml_document_struct(page);
7622|		_root->prev_sibling_c = _root;
7623|
7624|		// setup sentinel page
7625|		page->allocator = static_cast<impl::xml_document_struct*>(_root);
7626|
7627|		// setup hash table pointer in allocator
7628|	#ifdef PUGIXML_COMPACT
7629|		page->allocator->_hash = &static_cast<impl::xml_document_struct*>(_root)->hash;
7630|	#endif
7631|
7632|		// verify the document allocation
7633|		assert(reinterpret_cast<char*>(_root) + sizeof(impl::xml_document_struct) <= _memory + sizeof(_memory));
7634|	}
