7636|	PUGI_IMPL_FN void xml_document::_destroy()
7637|	{
7638|		assert(_root);
7639|
7640|		// destroy static storage
7641|		if (_buffer)
7642|		{
7643|			impl::xml_memory::deallocate(_buffer);
7644|			_buffer = NULL;
7645|		}
7646|
7647|		// destroy extra buffers (note: no need to destroy linked list nodes, they're allocated using document allocator)
7648|		for (impl::xml_extra_buffer* extra = static_cast<impl::xml_document_struct*>(_root)->extra_buffers; extra; extra = extra->next)
7649|		{
7650|			if (extra->buffer) impl::xml_memory::deallocate(extra->buffer);
7651|		}
7652|
7653|		// destroy dynamic storage, leave sentinel page (it's in static memory)
7654|		impl::xml_memory_page* root_page = PUGI_IMPL_GETPAGE(_root);
7655|		assert(root_page && !root_page->prev);
7656|		assert(reinterpret_cast<char*>(root_page) >= _memory && reinterpret_cast<char*>(root_page) < _memory + sizeof(_memory));
7657|
7658|		for (impl::xml_memory_page* page = root_page->next; page; )
7659|		{
7660|			impl::xml_memory_page* next = page->next;
7661|
7662|			impl::xml_allocator::deallocate_page(page);
7663|
7664|			page = next;
7665|		}
7666|
7667|	#ifdef PUGIXML_COMPACT
7668|		// destroy hash table
7669|		static_cast<impl::xml_document_struct*>(_root)->hash.clear();
7670|	#endif
7671|
7672|		_root = NULL;
7673|	}
