7675|#ifdef PUGIXML_HAS_MOVE
7676|	PUGI_IMPL_FN void xml_document::_move(xml_document& rhs) PUGIXML_NOEXCEPT_IF_NOT_COMPACT
7677|	{
7678|		impl::xml_document_struct* doc = static_cast<impl::xml_document_struct*>(_root);
7679|		impl::xml_document_struct* other = static_cast<impl::xml_document_struct*>(rhs._root);
7680|
7681|		// save first child pointer for later; this needs hash access
7682|		xml_node_struct* other_first_child = other->first_child;
7683|
7684|	#ifdef PUGIXML_COMPACT
7685|		// reserve space for the hash table up front; this is the only operation that can fail
7686|		// if it does, we have no choice but to throw (if we have exceptions)
7687|		if (other_first_child)
7688|		{
7689|			size_t other_children = 0;
7690|			for (xml_node_struct* node = other_first_child; node; node = node->next_sibling)
7691|				other_children++;
7692|
7693|			// in compact mode, each pointer assignment could result in a hash table request
7694|			// during move, we have to relocate document first_child and parents of all children
7695|			// normally there's just one child and its parent has a pointerless encoding but
7696|			// we assume the worst here
7697|			if (!other->_hash->reserve(other_children + 1))
7698|			{
7699|			#ifdef PUGIXML_NO_EXCEPTIONS
7700|				return;
7701|			#else
7702|				throw std::bad_alloc();
7703|			#endif
7704|			}
7705|		}
7706|	#endif
7707|
7708|		// move allocation state
7709|		// note that other->_root may point to the embedded document page, in which case we should keep original (empty) state
7710|		if (other->_root != PUGI_IMPL_GETPAGE(other))
7711|		{
7712|			doc->_root = other->_root;
7713|			doc->_busy_size = other->_busy_size;
7714|		}
7715|
7716|		// move buffer state
7717|		doc->buffer = other->buffer;
7718|		doc->extra_buffers = other->extra_buffers;
7719|		_buffer = rhs._buffer;
7720|
7721|	#ifdef PUGIXML_COMPACT
7722|		// move compact hash; note that the hash table can have pointers to other but they will be "inactive", similarly to nodes removed with remove_child
7723|		doc->hash = other->hash;
7724|		doc->_hash = &doc->hash;
7725|
7726|		// make sure we don't access other hash up until the end when we reinitialize other document
7727|		other->_hash = NULL;
7728|	#endif
7729|
7730|		// move page structure
7731|		impl::xml_memory_page* doc_page = PUGI_IMPL_GETPAGE(doc);
7732|		assert(doc_page && !doc_page->prev && !doc_page->next);
7733|
7734|		impl::xml_memory_page* other_page = PUGI_IMPL_GETPAGE(other);
7735|		assert(other_page && !other_page->prev);
7736|
7737|		// relink pages since root page is embedded into xml_document
7738|		if (impl::xml_memory_page* page = other_page->next)
7739|		{
7740|			assert(page->prev == other_page);
7741|
7742|			page->prev = doc_page;
7743|
7744|			doc_page->next = page;
7745|			other_page->next = NULL;
7746|		}
7747|
7748|		// make sure pages point to the correct document state
7749|		for (impl::xml_memory_page* page = doc_page->next; page; page = page->next)
7750|		{
7751|			assert(page->allocator == other);
7752|
7753|			page->allocator = doc;
7754|
7755|		#ifdef PUGIXML_COMPACT
7756|			// this automatically migrates most children between documents and prevents ->parent assignment from allocating
7757|			if (page->compact_shared_parent == other)
7758|				page->compact_shared_parent = doc;
7759|		#endif
7760|		}
7761|
7762|		// move tree structure
7763|		assert(!doc->first_child);
7764|
7765|		doc->first_child = other_first_child;
7766|
7767|		for (xml_node_struct* node = other_first_child; node; node = node->next_sibling)
7768|		{
7769|		#ifdef PUGIXML_COMPACT
7770|			// most children will have migrated when we reassigned compact_shared_parent
7771|			assert(node->parent == other || node->parent == doc);
7772|
7773|			node->parent = doc;
7774|		#else
7775|			assert(node->parent == other);
7776|			node->parent = doc;
7777|		#endif
7778|		}
7779|
7780|		// reset other document
7781|		new (other) impl::xml_document_struct(other_page);
7782|		rhs._buffer = NULL;
7783|	}
7784|#endif
