8102|	template <typename T, typename Pred> PUGI_IMPL_FN void insertion_sort(T* begin, T* end, const Pred& pred)
8103|	{
8104|		if (begin == end)
8105|			return;
8106|
8107|		for (T* it = begin + 1; it != end; ++it)
8108|		{
8109|			T val = *it;
8110|			T* hole = it;
8111|
8112|			// move hole backwards
8113|			while (hole > begin && pred(val, *(hole - 1)))
8114|			{
8115|				*hole = *(hole - 1);
8116|				hole--;
8117|			}
8118|
8119|			// fill hole with element
8120|			*hole = val;
8121|		}
8122|	}
