8136|	template <typename T, typename Pred> PUGI_IMPL_FN void partition3(T* begin, T* end, T pivot, const Pred& pred, T** out_eqbeg, T** out_eqend)
8137|	{
8138|		// invariant: array is split into 4 groups: = < ? > (each variable denotes the boundary between the groups)
8139|		T* eq = begin;
8140|		T* lt = begin;
8141|		T* gt = end;
8142|
8143|		while (lt < gt)
8144|		{
8145|			if (pred(*lt, pivot))
8146|				lt++;
8147|			else if (*lt == pivot)
8148|				swap(*eq++, *lt++);
8149|			else
8150|				swap(*lt, *--gt);
8151|		}
8152|
8153|		// we now have just 3 groups: = < >; move equal elements to the middle
8154|		T* eqbeg = gt;
8155|
8156|		for (T* it = begin; it != eq; ++it)
8157|			swap(*it, *--eqbeg);
8158|
8159|		*out_eqbeg = eqbeg;
8160|		*out_eqend = gt;
8161|	}
