8163|	template <typename I, typename Pred> PUGI_IMPL_FN void sort(I begin, I end, const Pred& pred)
8164|	{
8165|		// sort large chunks
8166|		while (end - begin > 16)
8167|		{
8168|			// find median element
8169|			I middle = begin + (end - begin) / 2;
8170|			I median = median3(begin, middle, end - 1, pred);
8171|
8172|			// partition in three chunks (< = >)
8173|			I eqbeg, eqend;
8174|			partition3(begin, end, *median, pred, &eqbeg, &eqend);
8175|
8176|			// loop on larger half
8177|			if (eqbeg - begin > end - eqend)
8178|			{
8179|				sort(eqend, end, pred);
8180|				end = eqbeg;
8181|			}
8182|			else
8183|			{
8184|				sort(begin, eqbeg, pred);
8185|				begin = eqend;
8186|			}
8187|		}
8188|
8189|		// insertion sort small chunk
8190|		insertion_sort(begin, end, pred);
8191|	}
