8193|	PUGI_IMPL_FN bool hash_insert(const void** table, size_t size, const void* key)
8194|	{
8195|		assert(key);
8196|
8197|		unsigned int h = static_cast<unsigned int>(reinterpret_cast<uintptr_t>(key));
8198|
8199|		// MurmurHash3 32-bit finalizer
8200|		h ^= h >> 16;
8201|		h *= 0x85ebca6bu;
8202|		h ^= h >> 13;
8203|		h *= 0xc2b2ae35u;
8204|		h ^= h >> 16;
8205|
8206|		size_t hashmod = size - 1;
8207|		size_t bucket = h & hashmod;
8208|
8209|		for (size_t probe = 0; probe <= hashmod; ++probe)
8210|		{
8211|			if (table[bucket] == NULL)
8212|			{
8213|				table[bucket] = key;
8214|				return true;
8215|			}
8216|
8217|			if (table[bucket] == key)
8218|				return false;
8219|
8220|			// hash collision, quadratic probing
8221|			bucket = (bucket + probe + 1) & hashmod;
8222|		}
8223|
8224|		assert(false && "Hash table is full"); // unreachable
8225|		return false;
8226|	}
