8239|	static const uintptr_t xpath_memory_block_alignment = sizeof(double) > sizeof(void*) ? sizeof(double) : sizeof(void*);
8240|
8241|	struct xpath_memory_block
8242|	{
8243|		xpath_memory_block* next;
8244|		size_t capacity;
8245|
8246|		union
8247|		{
8248|			char data[xpath_memory_page_size];
8249|			double alignment;
8250|		};
8251|	};
8252|
8253|	struct xpath_allocator
8254|	{
8255|		xpath_memory_block* _root;
8256|		size_t _root_size;
8257|		bool* _error;
8258|
8259|		xpath_allocator(xpath_memory_block* root, bool* error = NULL): _root(root), _root_size(0), _error(error)
8260|		{
8261|		}
8262|
8263|		void* allocate(size_t size)
8264|		{
8265|			// round size up to block alignment boundary
8266|			size = (size + xpath_memory_block_alignment - 1) & ~(xpath_memory_block_alignment - 1);
8267|
8268|			if (_root_size + size <= _root->capacity)
8269|			{
8270|				void* buf = &_root->data[0] + _root_size;
8271|				_root_size += size;
8272|				return buf;
8273|			}
8274|			else
8275|			{
8276|				// make sure we have at least 1/4th of the page free after allocation to satisfy subsequent allocation requests
8277|				size_t block_capacity_base = sizeof(_root->data);
8278|				size_t block_capacity_req = size + block_capacity_base / 4;
8279|				size_t block_capacity = (block_capacity_base > block_capacity_req) ? block_capacity_base : block_capacity_req;
8280|
8281|				size_t block_size = block_capacity + offsetof(xpath_memory_block, data);
8282|
8283|				xpath_memory_block* block = static_cast<xpath_memory_block*>(xml_memory::allocate(block_size));
8284|				if (!block)
8285|				{
8286|					if (_error) *_error = true;
8287|					return NULL;
8288|				}
8289|
8290|				block->next = _root;
8291|				block->capacity = block_capacity;
8292|
8293|				_root = block;
8294|				_root_size = size;
8295|
8296|				return block->data;
8297|			}
8298|		}
8299|
8300|		void* reallocate(void* ptr, size_t old_size, size_t new_size)
8301|		{
8302|			// round size up to block alignment boundary
8303|			old_size = (old_size + xpath_memory_block_alignment - 1) & ~(xpath_memory_block_alignment - 1);
8304|			new_size = (new_size + xpath_memory_block_alignment - 1) & ~(xpath_memory_block_alignment - 1);
8305|
8306|			// we can only reallocate the last object
8307|			assert(ptr == NULL || static_cast<char*>(ptr) + old_size == &_root->data[0] + _root_size);
8308|
8309|			// try to reallocate the object inplace
8310|			if (ptr && _root_size - old_size + new_size <= _root->capacity)
8311|			{
8312|				_root_size = _root_size - old_size + new_size;
8313|				return ptr;
8314|			}
8315|
8316|			// allocate a new block
8317|			void* result = allocate(new_size);
8318|			if (!result) return NULL;
8319|
8320|			// we have a new block
8321|			if (ptr)
8322|			{
8323|				// copy old data (we only support growing)
8324|				assert(new_size >= old_size);
8325|				memcpy(result, ptr, old_size);
8326|
8327|				// free the previous page if it had no other objects
8328|				assert(_root->data == result);
8329|				assert(_root->next);
8330|
8331|				if (_root->next->data == ptr)
8332|				{
8333|					// deallocate the whole page, unless it was the first one
8334|					xpath_memory_block* next = _root->next->next;
8335|
8336|					if (next)
8337|					{
8338|						xml_memory::deallocate(_root->next);
8339|						_root->next = next;
8340|					}
8341|				}
8342|			}
8343|
8344|			return result;
8345|		}
