8686|	PUGI_IMPL_FN bool node_is_before(xml_node_struct* ln, xml_node_struct* rn)
8687|	{
8688|		// find common ancestor at the same depth, if any
8689|		xml_node_struct* lp = ln;
8690|		xml_node_struct* rp = rn;
8691|
8692|		while (lp && rp && lp->parent != rp->parent)
8693|		{
8694|			lp = lp->parent;
8695|			rp = rp->parent;
8696|		}
8697|
8698|		// parents are the same!
8699|		if (lp && rp) return node_is_before_sibling(lp, rp);
8700|
8701|		// nodes are at different depths, need to normalize heights
8702|		bool left_higher = !lp;
8703|
8704|		while (lp)
8705|		{
8706|			lp = lp->parent;
8707|			ln = ln->parent;
8708|		}
8709|
8710|		while (rp)
8711|		{
8712|			rp = rp->parent;
8713|			rn = rn->parent;
8714|		}
8715|
8716|		// one node is the ancestor of the other
8717|		if (ln == rn) return left_higher;
8718|
8719|		// find common ancestor... again
