8767|	struct document_order_comparator
8768|	{
8769|		bool operator()(const xpath_node& lhs, const xpath_node& rhs) const
8770|		{
8771|			// optimized document order based check
8772|			const void* lo = document_buffer_order(lhs);
8773|			const void* ro = document_buffer_order(rhs);
8774|
8775|			if (lo && ro) return lo < ro;
8776|
8777|			// slow comparison
8778|			xml_node ln = lhs.node(), rn = rhs.node();
8779|
8780|			// compare attributes
8781|			if (lhs.attribute() && rhs.attribute())
8782|			{
8783|				// shared parent
8784|				if (lhs.parent() == rhs.parent())
8785|				{
8786|					// determine sibling order
8787|					for (xml_attribute a = lhs.attribute(); a; a = a.next_attribute())
8788|						if (a == rhs.attribute())
8789|							return true;
8790|
8791|					return false;
8792|				}
8793|
8794|				// compare attribute parents
8795|				ln = lhs.parent();
8796|				rn = rhs.parent();
8797|			}
8798|			else if (lhs.attribute())
8799|			{
8800|				// attributes go after the parent element
8801|				if (lhs.parent() == rhs.node()) return false;
8802|
8803|				ln = lhs.parent();
8804|			}
8805|			else if (rhs.attribute())
8806|			{
8807|				// attributes go after the parent element
8808|				if (rhs.parent() == lhs.node()) return true;
8809|
8810|				rn = rhs.parent();
8811|			}
8812|
8813|			if (ln == rn) return false;
8814|
8815|			if (!ln || !rn) return ln < rn;
8816|
8817|			return node_is_before(ln.internal_object(), rn.internal_object());
8818|		}
