8911|	#ifdef PUGIXML_CHARCONV_FLOAT
8912|		std::to_chars_result res = std::to_chars(buffer, buffer + sizeof(buffer) - 1, value, std::chars_format::scientific, DBL_DIG);
8913|		assert(res.ec == std::errc());
8914|		*res.ptr = '\0';
8915|	#else
8916|		// get a scientific notation value with IEEE DBL_DIG decimals
8917|		PUGI_IMPL_SNPRINTF(buffer, "%.*e", DBL_DIG, value);
8918|	#endif
8919|		// get the exponent (possibly negative)
8920|		char* exponent_string = strchr(buffer, 'e');
8921|		assert(exponent_string);
8922|
8923|		char *s = exponent_string + 1;
8924|		bool isneg = *s++ == '-';
8925|		int exponent = 0;
8926|		while (*s) exponent = exponent * 10 + (*s++ - '0');
8927|		exponent = isneg ? -exponent : exponent;
8928|
8929|		// extract mantissa string: skip sign
8930|		char* mantissa = buffer[0] == '-' ? buffer + 1 : buffer;
8931|		assert(mantissa[0] != '0' && (mantissa[1] == '.' || mantissa[1] == ','));
8932|
8933|		// divide mantissa by 10 to eliminate integer part
8934|		mantissa[1] = mantissa[0];
8935|		mantissa++;
8936|		exponent++;
8937|
8938|		// remove extra mantissa digits and zero-terminate mantissa
8939|		truncate_zeros(mantissa, exponent_string);
8940|
8941|		// fill results
8942|		*out_mantissa = mantissa;
8943|		*out_exponent = exponent;
8944|	}
8945|#endif
