8947|	PUGI_IMPL_FN xpath_string convert_number_to_string(double value, xpath_allocator* alloc)
8948|	{
8949|		// try special number conversion
8950|		const char_t* special = convert_number_to_string_special(value);
8951|		if (special) return xpath_string::from_const(special);
8952|
8953|		// get mantissa + exponent form
8954|		char mantissa_buffer[32];
8955|
8956|		char* mantissa;
8957|		int exponent;
8958|		convert_number_to_mantissa_exponent(value, mantissa_buffer, &mantissa, &exponent);
8959|
8960|		// allocate a buffer of suitable length for the number
8961|		size_t result_size = strlen(mantissa_buffer) + (exponent > 0 ? exponent : -exponent) + 4;
8962|		char_t* result = static_cast<char_t*>(alloc->allocate(sizeof(char_t) * result_size));
8963|		if (!result) return xpath_string();
8964|
8965|		// make the number!
8966|		char_t* s = result;
8967|
8968|		// sign
8969|		if (value < 0) *s++ = '-';
8970|
8971|		// integer part
8972|		if (exponent <= 0)
8973|		{
8974|			*s++ = '0';
8975|		}
8976|		else
8977|		{
8978|			while (exponent > 0)
8979|			{
8980|				assert(*mantissa == 0 || static_cast<unsigned int>(*mantissa - '0') <= 9);
8981|				*s++ = *mantissa ? *mantissa++ : '0';
8982|				exponent--;
8983|			}
8984|		}
8985|
8986|		// fractional part
8987|		if (*mantissa)
8988|		{
8989|			// decimal point
8990|			*s++ = '.';
8991|
8992|			// extra zeroes from negative exponent
8993|			while (exponent < 0)
8994|			{
8995|				*s++ = '0';
8996|				exponent++;
8997|			}
8998|
8999|			// extra mantissa digits
9000|			while (*mantissa)
9001|			{
9002|				assert(static_cast<unsigned int>(*mantissa - '0') <= 9);
9003|				*s++ = *mantissa++;
9004|			}
9005|		}
9006|
9007|		// zero-terminate
9008|		assert(s < result + result_size);
