9228|	PUGI_IMPL_FN unsigned char* translate_table_generate(xpath_allocator* alloc, const char_t* from, const char_t* to)
9229|	{
9230|		unsigned char table[128] = {0};
9231|
9232|		while (*from)
9233|		{
9234|			unsigned int fc = static_cast<unsigned int>(*from);
9235|			unsigned int tc = static_cast<unsigned int>(*to);
9236|
9237|			if (fc >= 128 || tc >= 128)
