9245|			if (tc) to++;
9246|		}
9247|
9248|		for (int i = 0; i < 128; ++i)
9249|			if (!table[i])
9250|				table[i] = static_cast<unsigned char>(i);
9251|
9252|		void* result = alloc->allocate(sizeof(table));
9253|		if (!result) return NULL;
9254|
9255|		memcpy(result, table, sizeof(table));
9256|
9257|		return static_cast<unsigned char*>(result);
9258|	}
