9633|
9634|				size_t hash_size = 1;
9635|				while (hash_size < size_ + size_ / 2) hash_size *= 2;
9636|
9637|				const void** hash_data = static_cast<const void**>(alloc->allocate(hash_size * sizeof(void*)));
9638|				if (!hash_data) return;
9639|
9640|				memset(hash_data, 0, hash_size * sizeof(void*));
