10392|		static void apply_predicate_boolean(xpath_node_set_raw& ns, size_t first, xpath_ast_node* expr, const xpath_stack& stack, bool once)
10393|		{
10394|			assert(ns.size() >= first);
10395|			assert(expr->rettype() != xpath_type_number);
10396|
10397|			size_t i = 1;
10398|			size_t size = ns.size() - first;
10399|
10400|			xpath_node* last = ns.begin() + first;
10401|
10402|			// remove_if... or well, sort of
10403|			for (xpath_node* it = last; it != ns.end(); ++it, ++i)
10404|			{
10405|				xpath_context c(*it, i, size);
10406|
10407|				if (expr->eval_boolean(c, stack))
10408|				{
10409|					*last++ = *it;
10410|
10411|					if (once) break;
10412|				}
10413|			}
10414|
10415|			ns.truncate(last);
10416|		}
