10421|			assert(expr->rettype() == xpath_type_number);
10422|
10423|			size_t i = 1;
10424|			size_t size = ns.size() - first;
10425|
10426|			xpath_node* last = ns.begin() + first;
10427|
10428|			// remove_if... or well, sort of
10429|			for (xpath_node* it = last; it != ns.end(); ++it, ++i)
10430|			{
10431|				xpath_context c(*it, i, size);
10432|
10433|				if (expr->eval_number(c, stack) == static_cast<double>(i))
10434|				{
10435|					*last++ = *it;
10436|
10437|					if (once) break;
10438|				}
10439|			}
10440|
10441|			ns.truncate(last);
10442|		}
