10444|		static void apply_predicate_number_const(xpath_node_set_raw& ns, size_t first, xpath_ast_node* expr, const xpath_stack& stack)
10445|		{
10446|			assert(ns.size() >= first);
10447|			assert(expr->rettype() == xpath_type_number);
10448|
10449|			size_t size = ns.size() - first;
10450|
10451|			xpath_node* last = ns.begin() + first;
10452|
10453|			xpath_node cn;
10454|			xpath_context c(cn, 1, size);
10455|
10456|			double er = expr->eval_number(c, stack);
10457|
10458|			if (er >= 1.0 && er <= static_cast<double>(size))
10459|			{
10460|				size_t eri = static_cast<size_t>(er);
10461|
10462|				if (er == static_cast<double>(eri))
10463|				{
10464|					xpath_node r = last[eri - 1];
10465|
10466|					*last++ = r;
10467|				}
10468|			}
10469|
10470|			ns.truncate(last);
10471|		}
