10473|		void apply_predicate(xpath_node_set_raw& ns, size_t first, const xpath_stack& stack, bool once)
10474|		{
10475|			if (ns.size() == first) return;
10476|
10477|			assert(_type == ast_filter || _type == ast_predicate);
10478|
10479|			if (_test == predicate_constant || _test == predicate_constant_one)
10480|				apply_predicate_number_const(ns, first, _right, stack);
