10605|		template <class T> void step_fill(xpath_node_set_raw& ns, xml_node_struct* n, xpath_allocator* alloc, bool once, T)
10606|		{
10607|			const axis_t axis = T::axis;
10608|
10609|			switch (axis)
10610|			{
10611|			case axis_attribute:
10612|			{
10613|				if (_test == nodetest_name)
10614|				{
10615|					for (xml_attribute_struct* a = n->first_attribute; a; a = a->next_attribute)
10616|						if (a->name && strequal(a->name, _data.nodetest) && is_xpath_attribute(a->name))
10617|						{
10618|							ns.push_back(xpath_node(xml_attribute(a), xml_node(n)), alloc);
10619|							return; // once=true by construction
10620|						}
10621|				}
10622|				else
10623|				{
10624|					for (xml_attribute_struct* a = n->first_attribute; a; a = a->next_attribute)
10625|						if (step_push(ns, a, n, alloc) & once)
10626|							return;
10627|				}
10628|
10629|				break;
10630|			}
10631|
10632|			case axis_child:
10633|			{
10634|				if (_test == nodetest_name)
10635|				{
10636|					for (xml_node_struct* c = n->first_child; c; c = c->next_sibling)
10637|						if (c->name && strequal(c->name, _data.nodetest) && PUGI_IMPL_NODETYPE(c) == node_element)
