10644|				{
10645|					for (xml_node_struct* c = n->first_child; c; c = c->next_sibling)
10646|						if (step_push(ns, c, alloc) & once)
10647|							return;
10648|				}
10649|
10650|				break;
10651|			}
10652|
10653|			case axis_descendant:
10654|			case axis_descendant_or_self:
10655|			{
10656|				if (axis == axis_descendant_or_self)
10657|					if (step_push(ns, n, alloc) & once)
10658|						return;
