10660|				xml_node_struct* cur = n->first_child;
10661|
10662|				while (cur)
10663|				{
10664|					if (step_push(ns, cur, alloc) & once)
10665|						return;
10666|
10667|					if (cur->first_child)
10668|						cur = cur->first_child;
10669|					else
10670|					{
10671|						while (!cur->next_sibling)
10672|						{
10673|							cur = cur->parent;
10674|
10675|							if (cur == n) return;
10676|						}
10677|
10678|						cur = cur->next_sibling;
10679|					}
10680|				}
10681|
10682|				break;
10683|			}
10684|
10685|			case axis_following_sibling:
10686|			{
10687|				for (xml_node_struct* c = n->next_sibling; c; c = c->next_sibling)
10688|					if (step_push(ns, c, alloc) & once)
10689|						return;
10690|
10691|				break;
10692|			}
10693|
10694|			case axis_preceding_sibling:
10695|			{
10696|				for (xml_node_struct* c = n->prev_sibling_c; c->next_sibling; c = c->prev_sibling_c)
