10699|
10700|				break;
10701|			}
10702|
10703|			case axis_following:
10704|			{
10705|				xml_node_struct* cur = n;
10706|
10707|				// exit from this node so that we don't include descendants
10708|				while (!cur->next_sibling)
10709|				{
10710|					cur = cur->parent;
10711|
10712|					if (!cur) return;
10713|				}
10714|
10715|				cur = cur->next_sibling;
10716|
10717|				while (cur)
10718|				{
10719|					if (step_push(ns, cur, alloc) & once)
10720|						return;
10721|
10722|					if (cur->first_child)
10723|						cur = cur->first_child;
10724|					else
10725|					{
10726|						while (!cur->next_sibling)
10727|						{
10728|							cur = cur->parent;
10729|
10730|							if (!cur) return;
10731|						}
10732|
10733|						cur = cur->next_sibling;
10734|					}
10735|				}
10736|
10737|				break;
