10851|				if (_test == nodetest_type_node) // reject attributes based on principal node type test
10852|					step_push(ns, a, p, alloc);
10853|
10854|				break;
10855|			}
10856|
10857|			case axis_following:
10858|			{
10859|				xml_node_struct* cur = p;
10860|
10861|				while (cur)
10862|				{
10863|					if (cur->first_child)
10864|						cur = cur->first_child;
10865|					else
10866|					{
10867|						while (!cur->next_sibling)
10868|						{
10869|							cur = cur->parent;
10870|
10871|							if (!cur) return;
10872|						}
10873|
10874|						cur = cur->next_sibling;
10875|					}
10876|
10877|					if (step_push(ns, cur, alloc) & once)
10878|						return;
10879|				}
10880|
10881|				break;
10882|			}
10883|
10884|			case axis_parent:
10885|			{
10886|				step_push(ns, p, alloc);
10887|
10888|				break;
10889|			}
10890|
10891|			case axis_preceding:
10892|			{
10893|				// preceding:: axis does not include attribute nodes and attribute ancestors (they are the same as parent's ancestors), so we can reuse node preceding
10894|				step_fill(ns, p, alloc, once, v);
10895|				break;
10896|			}
10897|
10898|			default:
10899|				assert(false && "Unimplemented axis"); // unreachable
10900|			}
10901|		}
