10903|		template <class T> void step_fill(xpath_node_set_raw& ns, const xpath_node& xn, xpath_allocator* alloc, bool once, T v)
10904|		{
10905|			const axis_t axis = T::axis;
10906|			const bool axis_has_attributes = (axis == axis_ancestor || axis == axis_ancestor_or_self || axis == axis_descendant_or_self || axis == axis_following || axis == axis_parent || axis == axis_preceding || axis == axis_self);
10907|
10908|			if (xn.node())
10909|				step_fill(ns, xn.node().internal_object(), alloc, once, v);
10910|			else if (axis_has_attributes && xn.attribute() && xn.parent())
10911|				step_fill(ns, xn.attribute().internal_object(), xn.parent().internal_object(), alloc, once, v);
10912|		}
