10914|		template <class T> xpath_node_set_raw step_do(const xpath_context& c, const xpath_stack& stack, nodeset_eval_t eval, T v)
10915|		{
10916|			const axis_t axis = T::axis;
10917|			const bool axis_reverse = (axis == axis_ancestor || axis == axis_ancestor_or_self || axis == axis_preceding || axis == axis_preceding_sibling);
10918|			const xpath_node_set::type_t axis_type = axis_reverse ? xpath_node_set::type_sorted_reverse : xpath_node_set::type_sorted;
10919|
10920|			bool once =
10921|				(axis == axis_attribute && _test == nodetest_name) ||
10922|				(!_right && eval_once(axis_type, eval)) ||
10923|			    // coverity[mixed_enums]
10924|				(_right && !_right->_next && _right->_test == predicate_constant_one);
10925|
10926|			xpath_node_set_raw ns;
10927|			ns.set_type(axis_type);
10928|
10929|			if (_left)
10930|			{
10931|				xpath_node_set_raw s = _left->eval_node_set(c, stack, nodeset_eval_all);
10932|
10933|				// self axis preserves the original order
10934|				if (axis == axis_self) ns.set_type(s.type());
10935|
10936|				for (const xpath_node* it = s.begin(); it != s.end(); ++it)
10937|				{
10938|					size_t size = ns.size();
10939|
10940|					// in general, all axes generate elements in a particular order, but there is no order guarantee if axis is applied to two nodes
10941|					if (axis != axis_self && size != 0) ns.set_type(xpath_node_set::type_unsorted);
10942|
10943|					step_fill(ns, *it, stack.result, once, v);
10944|					if (_right) apply_predicates(ns, size, stack, eval);
10945|				}
10946|			}
10947|			else
10948|			{
10949|				step_fill(ns, c.n, stack.result, once, v);
10950|				if (_right) apply_predicates(ns, 0, stack, eval);
10951|			}
10952|
10953|			// child, attribute and self axes always generate unique set of nodes
10954|			// for other axis, if the set stayed sorted, it stayed unique because the traversal algorithms do not visit the same node twice
10955|			if (axis != axis_child && axis != axis_attribute && axis != axis_self && ns.type() == xpath_node_set::type_unsorted)
10956|				ns.remove_duplicates(stack.temp);
10957|
10958|			return ns;
10959|		}
