11048|
11049|			case ast_func_contains:
11050|			{
11051|				xpath_allocator_capture cr(stack.result);
11052|
11053|				xpath_string lr = _left->eval_string(c, stack);
11054|				xpath_string rr = _right->eval_string(c, stack);
