11310|
11311|			// evaluate all strings to temporary stack
11312|			xpath_stack swapped_stack = {stack.temp, stack.result};
11313|
11314|			buffer[0] = _left->eval_string(c, swapped_stack);
11315|
11316|			size_t pos = 1;
11317|			for (xpath_ast_node* n = _right; n; n = n->_next, ++pos) buffer[pos] = n->eval_string(c, swapped_stack);
11318|			assert(pos == count);
11319|
11320|			// get total length
11321|			size_t length = 0;
11322|			for (size_t i = 0; i < count; ++i) length += buffer[i].length();
11323|
11324|			// create final string
11325|			char_t* result = static_cast<char_t*>(stack.result->allocate((length + 1) * sizeof(char_t)));
11326|			if (!result) return xpath_string();
11327|
11328|			char_t* ri = result;
11329|
11330|			for (size_t j = 0; j < count; ++j)
11331|				for (const char_t* bi = buffer[j].c_str(); *bi; ++bi)
11332|					*ri++ = *bi;
