11415|				const char_t* pos = find_substring(s.c_str(), p.c_str());
11416|
11417|				return pos ? xpath_string::from_heap(s.c_str(), pos, stack.result) : xpath_string();
11418|			}
11419|
11420|			case ast_func_substring_after:
11421|			{
11422|				xpath_allocator_capture cr(stack.temp);
11423|
11424|				xpath_stack swapped_stack = {stack.temp, stack.result};
11425|
11426|				xpath_string s = _left->eval_string(c, swapped_stack);
11427|				xpath_string p = _right->eval_string(c, swapped_stack);
11428|
11429|				const char_t* pos = find_substring(s.c_str(), p.c_str());
11430|				if (!pos) return xpath_string();
11431|
11432|				const char_t* rbegin = pos + p.length();
11433|				const char_t* rend = s.c_str() + s.length();
11434|
