11437|
11438|			case ast_func_substring_2:
11439|			{
11440|				xpath_allocator_capture cr(stack.temp);
11441|
11442|				xpath_stack swapped_stack = {stack.temp, stack.result};
11443|
11444|				xpath_string s = _left->eval_string(c, swapped_stack);
11445|				size_t s_length = s.length();
11446|
11447|				double first = round_nearest(_right->eval_number(c, stack));
11448|
11449|				if (is_nan(first)) return xpath_string(); // NaN
11450|				else if (first >= static_cast<double>(s_length + 1)) return xpath_string();
11451|
11452|				size_t pos = first < 1 ? 1 : static_cast<size_t>(first);
11453|				assert(1 <= pos && pos <= s_length + 1);
11454|
11455|				const char_t* rbegin = s.c_str() + (pos - 1);
11456|				const char_t* rend = s.c_str() + s.length();
11457|
11458|				return s.uses_heap() ? xpath_string::from_heap(rbegin, rend, stack.result) : xpath_string::from_const(rbegin);
