11465|				xpath_stack swapped_stack = {stack.temp, stack.result};
11466|
11467|				xpath_string s = _left->eval_string(c, swapped_stack);
11468|				size_t s_length = s.length();
11469|
11470|				double first = round_nearest(_right->eval_number(c, stack));
11471|				double last = first + round_nearest(_right->_next->eval_number(c, stack));
11472|
11473|				if (is_nan(first) || is_nan(last)) return xpath_string();
11474|				else if (first >= static_cast<double>(s_length + 1)) return xpath_string();
11475|				else if (first >= last) return xpath_string();
11476|				else if (last < 1) return xpath_string();
11477|
11478|				size_t pos = first < 1 ? 1 : static_cast<size_t>(first);
11479|				size_t end = last >= static_cast<double>(s_length + 1) ? s_length + 1 : static_cast<size_t>(last);
11480|
11481|				assert(1 <= pos && pos <= end && end <= s_length + 1);
11482|				const char_t* rbegin = s.c_str() + (pos - 1);
11483|				const char_t* rend = s.c_str() + (end - 1);
11484|
11485|				return (end == s_length + 1 && !s.uses_heap()) ? xpath_string::from_const(rbegin) : xpath_string::from_heap(rbegin, rend, stack.result);
