11487|
11488|			case ast_func_normalize_space_0:
11489|			{
11490|				xpath_string s = string_value(c.n, stack.result);
11491|
11492|				char_t* begin = s.data(stack.result);
11493|				if (!begin) return xpath_string();
11494|
11495|				char_t* end = normalize_space(begin);
11496|
11497|				return xpath_string::from_heap_preallocated(begin, end);
11498|			}
11499|
11500|			case ast_func_normalize_space_1:
11501|			{
11502|				xpath_string s = _left->eval_string(c, stack);
11503|
11504|				char_t* begin = s.data(stack.result);
11505|				if (!begin) return xpath_string();
11506|
11507|				char_t* end = normalize_space(begin);
11508|
11509|				return xpath_string::from_heap_preallocated(begin, end);
11510|			}
11511|
11512|			case ast_func_translate:
11513|			{
11514|				xpath_allocator_capture cr(stack.temp);
11515|
11516|				xpath_stack swapped_stack = {stack.temp, stack.result};
11517|
11518|				xpath_string s = _left->eval_string(c, stack);
11519|				xpath_string from = _right->eval_string(c, swapped_stack);
11520|				xpath_string to = _right->_next->eval_string(c, swapped_stack);
11521|
11522|				char_t* begin = s.data(stack.result);
11523|				if (!begin) return xpath_string();
11524|
11525|				char_t* end = translate(begin, from.c_str(), to.c_str(), to.length());
