11529|
11530|			case ast_opt_translate_table:
11531|			{
11532|				xpath_string s = _left->eval_string(c, stack);
11533|
11534|				char_t* begin = s.data(stack.result);
11535|				if (!begin) return xpath_string();
11536|
11537|				char_t* end = translate_table(begin, _data.table);
