11546|				return attr ? xpath_string::from_const(attr.value()) : xpath_string();
11547|			}
11548|
11549|			case ast_variable:
11550|			{
11551|				assert(_rettype == _data.variable->type());
11552|
11553|				if (_rettype == xpath_type_string)
11554|					return xpath_string::from_const(_data.variable->get_string());
11555|
11556|				// variable needs to be converted to the correct type, this is handled by the fallthrough block below
