11572|
11573|			case xpath_type_node_set:
11574|			{
11575|				xpath_allocator_capture cr(stack.temp);
11576|
11577|				xpath_stack swapped_stack = {stack.temp, stack.result};
11578|
11579|				xpath_node_set_raw ns = eval_node_set(c, swapped_stack, nodeset_eval_first);
