11588|
11589|		xpath_node_set_raw eval_node_set(const xpath_context& c, const xpath_stack& stack, nodeset_eval_t eval)
11590|		{
11591|			switch (_type)
11592|			{
11593|			case ast_op_union:
11594|			{
11595|				xpath_allocator_capture cr(stack.temp);
11596|
11597|				xpath_stack swapped_stack = {stack.temp, stack.result};
11598|
11599|				xpath_node_set_raw ls = _left->eval_node_set(c, stack, eval);
11600|				xpath_node_set_raw rs = _right->eval_node_set(c, swapped_stack, eval);
11601|
11602|				// we can optimize merging two sorted sets, but this is a very rare operation, so don't bother
11603|				ls.set_type(xpath_node_set::type_unsorted);
11604|
11605|				ls.append(rs.begin(), rs.end(), stack.result);
11606|				ls.remove_duplicates(stack.temp);
11607|
11608|				return ls;
11609|			}
11610|
11611|			case ast_filter:
11612|			{
11613|				xpath_node_set_raw set = _left->eval_node_set(c, stack, _test == predicate_constant_one ? nodeset_eval_first : nodeset_eval_all);
11614|
11615|				// either expression is a number or it contains position() call; sort by document order
11616|				if (_test != predicate_posinv) set.sort_do();
11617|
11618|				bool once = eval_once(set.type(), eval);
11619|
11620|				apply_predicate(set, 0, stack, once);
11621|
11622|				return set;
11623|			}
11624|
11625|			case ast_func_id:
11626|				return xpath_node_set_raw();
11627|
11628|			case ast_step:
11629|			{
11630|				switch (_axis)
11631|				{
11632|				case axis_ancestor:
11633|					return step_do(c, stack, eval, axis_to_type<axis_ancestor>());
11634|
11635|				case axis_ancestor_or_self:
11636|					return step_do(c, stack, eval, axis_to_type<axis_ancestor_or_self>());
11637|
11638|				case axis_attribute:
11639|					return step_do(c, stack, eval, axis_to_type<axis_attribute>());
11640|
11641|				case axis_child:
11642|					return step_do(c, stack, eval, axis_to_type<axis_child>());
11643|
11644|				case axis_descendant:
11645|					return step_do(c, stack, eval, axis_to_type<axis_descendant>());
11646|
11647|				case axis_descendant_or_self:
11648|					return step_do(c, stack, eval, axis_to_type<axis_descendant_or_self>());
11649|
11650|				case axis_following:
11651|					return step_do(c, stack, eval, axis_to_type<axis_following>());
11652|
11653|				case axis_following_sibling:
11654|					return step_do(c, stack, eval, axis_to_type<axis_following_sibling>());
11655|
11656|				case axis_namespace:
11657|					// namespaced axis is not supported
11658|					return xpath_node_set_raw();
11659|
11660|				case axis_parent:
11661|					return step_do(c, stack, eval, axis_to_type<axis_parent>());
11662|
11663|				case axis_preceding:
11664|					return step_do(c, stack, eval, axis_to_type<axis_preceding>());
11665|
11666|				case axis_preceding_sibling:
11667|					return step_do(c, stack, eval, axis_to_type<axis_preceding_sibling>());
11668|
11669|				case axis_self:
11670|					return step_do(c, stack, eval, axis_to_type<axis_self>());
11671|
11672|				default:
11673|					assert(false && "Unknown axis"); // unreachable
11674|					return xpath_node_set_raw();
11675|				}
11676|			}
11677|
11678|			case ast_step_root:
11679|			{
11680|				assert(!_right); // root step can't have any predicates
11681|
11682|				xpath_node_set_raw ns;
11683|				ns.set_type(xpath_node_set::type_sorted);
11684|
11685|				if (c.n.node()) ns.push_back(c.n.node().root(), stack.result);
11686|				else if (c.n.attribute()) ns.push_back(c.n.parent().root(), stack.result);
11687|
11688|				return ns;
11689|			}
11690|
11691|			case ast_opt_select_attribute:
11692|			{
11693|				xpath_node_set_raw ns;
11694|				ns.set_type(xpath_node_set::type_sorted);
11695|
11696|				xml_attribute attr = c.n.node().attribute(_data.nodetest);
11697|				if (attr) ns.push_back(xpath_node(attr, c.n.node()), stack.result);
11698|
11699|				return ns;
11700|			}
11701|
11702|			case ast_variable:
11703|			{
11704|				assert(_rettype == _data.variable->type());
11705|
11706|				if (_rettype == xpath_type_node_set)
11707|				{
11708|					const xpath_node_set& s = _data.variable->get_node_set();
11709|
11710|					xpath_node_set_raw ns;
11711|
11712|					ns.set_type(s.type());
11713|					ns.append(s.begin(), s.end(), stack.result);
11714|
11715|					return ns;
11716|				}
11717|
11718|				// variable needs to be converted to the correct type, this is handled by the fallthrough block below
11719|				break;
11720|			}
11721|
11722|			default:
11723|				;
11724|			}
11725|
11726|			// none of the ast types that return the value directly matched, but conversions to node set are invalid
11727|			assert(false && "Wrong expression for return type node set"); // unreachable
