11731|		void optimize(xpath_allocator* alloc)
11732|		{
11733|			if (_left)
11734|				_left->optimize(alloc);
11735|
11736|			if (_right)
11737|				_right->optimize(alloc);
11738|
11739|			if (_next)
11740|				_next->optimize(alloc);
11741|
11742|			// coverity[var_deref_model]
11743|			optimize_self(alloc);
11744|		}
11745|
11746|		void optimize_self(xpath_allocator* alloc)
11747|		{
11748|			// Rewrite [position()=expr] with [expr]
11749|			// Note that this step has to go before classification to recognize [position()=1]
11750|			if ((_type == ast_filter || _type == ast_predicate) &&
11751|				_right && // workaround for clang static analyzer (_right is never null for ast_filter/ast_predicate)
11752|				_right->_type == ast_op_equal && _right->_left->_type == ast_func_position && _right->_right->_rettype == xpath_type_number)
11753|			{
11754|				_right = _right->_right;
11755|			}
11756|
11757|			// Classify filter/predicate ops to perform various optimizations during evaluation
11758|			if ((_type == ast_filter || _type == ast_predicate) && _right) // workaround for clang static analyzer (_right is never null for ast_filter/ast_predicate)
11759|			{
11760|				assert(_test == predicate_default);
11761|
11762|				if (_right->_type == ast_number_constant && _right->_data.number == 1.0)
11763|					_test = predicate_constant_one;
11764|				else if (_right->_rettype == xpath_type_number && (_right->_type == ast_number_constant || _right->_type == ast_variable || _right->_type == ast_func_last))
11765|					_test = predicate_constant;
11766|				else if (_right->_rettype != xpath_type_number && _right->is_posinv_expr())
11767|					_test = predicate_posinv;
11768|			}
11769|
11770|			// Rewrite descendant-or-self::node()/child::foo with descendant::foo
11771|			// The former is a full form of //foo, the latter is much faster since it executes the node test immediately
11772|			// Do a similar kind of rewrite for self/descendant/descendant-or-self axes
11773|			// Note that we only rewrite positionally invariant steps (//foo[1] != /descendant::foo[1])
11774|			if (_type == ast_step && (_axis == axis_child || _axis == axis_self || _axis == axis_descendant || _axis == axis_descendant_or_self) &&
11775|				_left && _left->_type == ast_step && _left->_axis == axis_descendant_or_self && _left->_test == nodetest_type_node && !_left->_right &&
11776|				is_posinv_step())
11777|			{
11778|				if (_axis == axis_child || _axis == axis_descendant)
11779|					_axis = axis_descendant;
11780|				else
11781|					_axis = axis_descendant_or_self;
11782|
11783|				_left = _left->_left;
11784|			}
11785|
11786|			// Use optimized lookup table implementation for translate() with constant arguments
11787|			if (_type == ast_func_translate &&
11788|				_right && // workaround for clang static analyzer (_right is never null for ast_func_translate)
11789|				_right->_type == ast_string_constant && _right->_next->_type == ast_string_constant)
11790|			{
11791|				unsigned char* table = translate_table_generate(alloc, _right->_data.string, _right->_next->_data.string);
11792|
11793|				if (table)
11794|				{
11795|					_type = ast_opt_translate_table;
11796|					_data.table = table;
11797|				}
11798|			}
11799|
11800|			// Use optimized path for simple attribute selection (@attr)
11801|			// coverity[mixed_enums]
11802|			if (_type == ast_step && _axis == axis_attribute && _test == nodetest_name && !_left && !_right && is_xpath_attribute(_data.nodetest))
11803|			{
11804|				_type = ast_opt_select_attribute;
11805|			}
11806|
11807|			// Use optimized path for @attr = 'value' or @attr = $value (relies on attribute selection optimization for matching)
11808|			if (_type == ast_op_equal &&
11809|				_left && _right && // workaround for clang static analyzer and Coverity (_left and _right are never null for ast_op_equal)
11810|				_left->_type == ast_opt_select_attribute &&
11811|				(_right->_type == ast_string_constant || (_right->_type == ast_variable && _right->_rettype == xpath_type_string)))
11812|			{
11813|				_type = ast_opt_compare_attribute;
11814|			}
11815|		}
11816|
11817|		bool is_posinv_expr() const
11818|		{
11819|			switch (_type)
11820|			{
11821|			case ast_func_position:
11822|			case ast_func_last:
11823|				return false;
11824|
11825|			case ast_string_constant:
11826|			case ast_number_constant:
11827|			case ast_variable:
11828|				return true;
11829|
11830|			case ast_step:
11831|			case ast_step_root:
11832|				return true;
11833|
11834|			case ast_predicate:
11835|			case ast_filter:
11836|				return true;
11837|
11838|			default:
11839|				if (_left && !_left->is_posinv_expr()) return false;
11840|
11841|				for (xpath_ast_node* n = _right; n; n = n->_next)
11842|					if (!n->is_posinv_expr()) return false;
11843|
11844|				return true;
11845|			}
11846|		}
11847|
11848|		bool is_posinv_step() const
11849|		{
11850|			assert(_type == ast_step);
11851|
11852|			for (xpath_ast_node* n = _right; n; n = n->_next)
11853|			{
11854|				assert(n->_type == ast_predicate);
11855|
11856|				if (n->_test != predicate_posinv)
11857|					return false;
11858|			}
11859|
11860|			return true;
11861|		}
