12192|		// PrimaryExpr ::= VariableReference | '(' Expr ')' | Literal | Number | FunctionCall
12193|		xpath_ast_node* parse_primary_expression()
12194|		{
12195|			switch (_lexer.current())
12196|			{
12197|			case lex_var_ref:
12198|			{
12199|				xpath_lexer_string name = _lexer.contents();
12200|
12201|				if (!_variables)
12202|					return error("Unknown variable: variable set is not provided");
12203|
12204|				xpath_variable* var = NULL;
12205|				if (!get_variable_scratch(_scratch, _variables, name.begin, name.end, &var))
12206|					return error_oom();
12207|
12208|				if (!var)
12209|					return error("Unknown variable: variable set does not contain the given name");
12210|
12211|				_lexer.next();
12212|
12213|				return alloc_node(ast_variable, var->type(), var);
12214|			}
12215|
12216|			case lex_open_brace:
12217|			{
12218|				_lexer.next();
12219|
12220|				xpath_ast_node* n = parse_expression();
12221|				if (!n) return NULL;
12222|
12223|				if (_lexer.current() != lex_close_brace)
12224|					return error("Expected ')' to match an opening '('");
12225|
12226|				_lexer.next();
12227|
12228|				return n;
12229|			}
12230|
12231|			case lex_quoted_string:
12232|			{
12233|				const char_t* value = alloc_string(_lexer.contents());
12234|				if (!value) return NULL;
12235|
12236|				_lexer.next();
12237|
12238|				return alloc_node(ast_string_constant, xpath_type_string, value);
12239|			}
12240|
12241|			case lex_number:
12242|			{
12243|				double value = 0;
12244|
12245|				if (!convert_string_to_number_scratch(_scratch, _lexer.contents().begin, _lexer.contents().end, &value))
12246|					return error_oom();
12247|
12248|				_lexer.next();
12249|
12250|				return alloc_node(ast_number_constant, xpath_type_number, value);
12251|			}
12252|
12253|			case lex_string:
12254|			{
12255|				xpath_ast_node* args[2] = {NULL};
12256|				size_t argc = 0;
12257|
12258|				xpath_lexer_string function = _lexer.contents();
12259|				_lexer.next();
12260|
12261|				xpath_ast_node* last_arg = NULL;
12262|
12263|				if (_lexer.current() != lex_open_brace)
12264|					return error("Unrecognized function call");
12265|				_lexer.next();
12266|
12267|				size_t old_depth = _depth;
12268|
12269|				while (_lexer.current() != lex_close_brace)
12270|				{
12271|					if (argc > 0)
12272|					{
12273|						if (_lexer.current() != lex_comma)
12274|							return error("No comma between function arguments");
12275|						_lexer.next();
12276|					}
12277|
12278|					if (++_depth > xpath_ast_depth_limit)
12279|						return error_rec();
12280|
12281|					xpath_ast_node* n = parse_expression();
12282|					if (!n) return NULL;
12283|
12284|					if (argc < 2) args[argc] = n;
12285|					else last_arg->set_next(n);
12286|
12287|					argc++;
12288|					last_arg = n;
12289|				}
12290|
12291|				_lexer.next();
12292|
12293|				_depth = old_depth;
12294|
12295|				return parse_function(function, argc, args);
12296|			}
12297|
12298|			default:
12299|				return error("Unrecognizable primary expression");
12300|			}
12301|		}
