12340|		// Step ::= AxisSpecifier NodeTest Predicate* | AbbreviatedStep
12341|		// AxisSpecifier ::= AxisName '::' | '@'?
12342|		// NodeTest ::= NameTest | NodeType '(' ')' | 'processing-instruction' '(' Literal ')'
12343|		// NameTest ::= '*' | NCName ':' '*' | QName
12344|		// AbbreviatedStep ::= '.' | '..'
12345|		xpath_ast_node* parse_step(xpath_ast_node* set)
12346|		{
12347|			if (set && set->rettype() != xpath_type_node_set)
12348|				return error("Step has to be applied to node set");
