12350|			bool axis_specified = false;
12351|			axis_t axis = axis_child; // implied child axis
12352|
12353|			if (_lexer.current() == lex_axis_attribute)
12354|			{
12355|				axis = axis_attribute;
12356|				axis_specified = true;
12357|
12358|				_lexer.next();
12359|			}
12360|			else if (_lexer.current() == lex_dot)
12361|			{
12362|				_lexer.next();
12363|
12364|				if (_lexer.current() == lex_open_square_brace)
12365|					return error("Predicates are not allowed after an abbreviated step");
