12367|				return alloc_node(ast_step, set, axis_self, nodetest_type_node, NULL);
12368|			}
12369|			else if (_lexer.current() == lex_double_dot)
12370|			{
12371|				_lexer.next();
12372|
12373|				if (_lexer.current() == lex_open_square_brace)
12374|					return error("Predicates are not allowed after an abbreviated step");
12375|
12376|				return alloc_node(ast_step, set, axis_parent, nodetest_type_node, NULL);
12377|			}
12378|
12379|			nodetest_t nt_type = nodetest_none;
12380|			xpath_lexer_string nt_name;
12381|
12382|			if (_lexer.current() == lex_string)
12383|			{
12384|				// node name test
12385|				nt_name = _lexer.contents();
12386|				_lexer.next();
12387|
12388|				// was it an axis name?
12389|				if (_lexer.current() == lex_double_colon)
12390|				{
12391|					// parse axis name
12392|					if (axis_specified)
12393|						return error("Two axis specifiers in one step");
12394|
12395|					axis = parse_axis_name(nt_name, axis_specified);
12396|
12397|					if (!axis_specified)
12398|						return error("Unknown axis");
12399|
12400|					// read actual node test
12401|					_lexer.next();
12402|
12403|					if (_lexer.current() == lex_multiply)
12404|					{
12405|						nt_type = nodetest_all;
12406|						nt_name = xpath_lexer_string();
12407|						_lexer.next();
12408|					}
12409|					else if (_lexer.current() == lex_string)
12410|					{
12411|						nt_name = _lexer.contents();
12412|						_lexer.next();
12413|					}
12414|					else
12415|					{
12416|						return error("Unrecognized node test");
12417|					}
12418|				}
12419|
12420|				if (nt_type == nodetest_none)
12421|				{
12422|					// node type test or processing-instruction
12423|					if (_lexer.current() == lex_open_brace)
12424|					{
12425|						_lexer.next();
12426|
12427|						if (_lexer.current() == lex_close_brace)
12428|						{
12429|							_lexer.next();
12430|
12431|							nt_type = parse_node_test_type(nt_name);
12432|
12433|							if (nt_type == nodetest_none)
12434|								return error("Unrecognized node type");
12435|
12436|							nt_name = xpath_lexer_string();
12437|						}
12438|						else if (nt_name == PUGIXML_TEXT("processing-instruction"))
12439|						{
12440|							if (_lexer.current() != lex_quoted_string)
12441|								return error("Only literals are allowed as arguments to processing-instruction()");
12442|
12443|							nt_type = nodetest_pi;
12444|							nt_name = _lexer.contents();
12445|							_lexer.next();
12446|
12447|							if (_lexer.current() != lex_close_brace)
12448|								return error("Unmatched brace near processing-instruction()");
12449|							_lexer.next();
12450|						}
12451|						else
12452|						{
12453|							return error("Unmatched brace near node type test");
12454|						}
12455|					}
12456|					// QName or NCName:*
12457|					else
12458|					{
12459|						if (nt_name.end - nt_name.begin > 2 && nt_name.end[-2] == ':' && nt_name.end[-1] == '*') // NCName:*
12460|						{
12461|							nt_name.end--; // erase *
12462|
12463|							nt_type = nodetest_all_in_namespace;
12464|						}
12465|						else
12466|						{
12467|							nt_type = nodetest_name;
12468|						}
12469|					}
12470|				}
12471|			}
12472|			else if (_lexer.current() == lex_multiply)
12473|			{
12474|				nt_type = nodetest_all;
12475|				_lexer.next();
12476|			}
12477|			else
12478|			{
12479|				return error("Unrecognized node test");
12480|			}
12481|
12482|			const char_t* nt_name_copy = alloc_string(nt_name);
12483|			if (!nt_name_copy) return NULL;
12484|
12485|			xpath_ast_node* n = alloc_node(ast_step, set, axis, nt_type, nt_name_copy);
12486|			if (!n) return NULL;
12487|
12488|			size_t old_depth = _depth;
12489|
12490|			xpath_ast_node* last = NULL;
12491|
12492|			while (_lexer.current() == lex_open_square_brace)
12493|			{
12494|				_lexer.next();
12495|
12496|				if (++_depth > xpath_ast_depth_limit)
12497|					return error_rec();
