12499|				xpath_ast_node* expr = parse_expression();
12500|				if (!expr) return NULL;
12501|
12502|				xpath_ast_node* pred = alloc_node(ast_predicate, NULL, expr, predicate_default);
12503|				if (!pred) return NULL;
12504|
12505|				if (_lexer.current() != lex_close_square_brace)
12506|					return error("Expected ']' to match an opening '['");
12507|				_lexer.next();
12508|
12509|				if (last) last->set_next(pred);
12510|				else n->set_right(pred);
12511|
12512|				last = pred;
12513|			}
12514|
12515|			_depth = old_depth;
12516|
12517|			return n;
12518|		}
