12528|			while (_lexer.current() == lex_slash || _lexer.current() == lex_double_slash)
12529|			{
12530|				lexeme_t l = _lexer.current();
12531|				_lexer.next();
12532|
12533|				if (l == lex_double_slash)
12534|				{
12535|					n = alloc_node(ast_step, n, axis_descendant_or_self, nodetest_type_node, NULL);
12536|					if (!n) return NULL;
12537|
12538|					++_depth;
12539|				}
12540|
12541|				if (++_depth > xpath_ast_depth_limit)
12542|					return error_rec();
12543|
12544|				n = parse_step(n);
12545|				if (!n) return NULL;
12546|			}
12547|
12548|			_depth = old_depth;
12549|
12550|			return n;
12551|		}
