12553|		// LocationPath ::= RelativeLocationPath | AbsoluteLocationPath
12554|		// AbsoluteLocationPath ::= '/' RelativeLocationPath? | '//' RelativeLocationPath
12555|		xpath_ast_node* parse_location_path()
12556|		{
12557|			if (_lexer.current() == lex_slash)
12558|			{
12559|				_lexer.next();
12560|
12561|				xpath_ast_node* n = alloc_node(ast_step_root, xpath_type_node_set);
12562|				if (!n) return NULL;
12563|
12564|				// relative location path can start from axis_attribute, dot, double_dot, multiply and string lexemes; any other lexeme means standalone root path
12565|				lexeme_t l = _lexer.current();
12566|
12567|				if (l == lex_string || l == lex_axis_attribute || l == lex_dot || l == lex_double_dot || l == lex_multiply)
12568|					return parse_relative_location_path(n);
12569|				else
12570|					return n;
12571|			}
12572|			else if (_lexer.current() == lex_double_slash)
12573|			{
12574|				_lexer.next();
12575|
12576|				xpath_ast_node* n = alloc_node(ast_step_root, xpath_type_node_set);
12577|				if (!n) return NULL;
12578|
12579|				n = alloc_node(ast_step, n, axis_descendant_or_self, nodetest_type_node, NULL);
12580|				if (!n) return NULL;
12581|
12582|				return parse_relative_location_path(n);
12583|			}
12584|
12585|			// else clause moved outside of if because of bogus warning 'control may reach end of non-void function being inlined' in gcc 4.0.1
12586|			return parse_relative_location_path(NULL);
12587|		}
12588|
12589|		// PathExpr ::= LocationPath
12590|		//				| FilterExpr
12591|		//				| FilterExpr '/' RelativeLocationPath
12592|		//				| FilterExpr '//' RelativeLocationPath
12593|		// UnionExpr ::= PathExpr | UnionExpr '|' PathExpr
12594|		// UnaryExpr ::= UnionExpr | '-' UnaryExpr
12595|		xpath_ast_node* parse_path_or_unary_expression()
12596|		{
12597|			// Clarification.
12598|			// PathExpr begins with either LocationPath or FilterExpr.
12599|			// FilterExpr begins with PrimaryExpr
12600|			// PrimaryExpr begins with '$' in case of it being a variable reference,
12601|			// '(' in case of it being an expression, string literal, number constant or
12602|			// function call.
12603|			if (_lexer.current() == lex_var_ref || _lexer.current() == lex_open_brace ||
12604|				_lexer.current() == lex_quoted_string || _lexer.current() == lex_number ||
12605|				_lexer.current() == lex_string)
12606|			{
12607|				if (_lexer.current() == lex_string)
12608|				{
12609|					// This is either a function call, or not - if not, we shall proceed with location path
12610|					const char_t* state = _lexer.state();
12611|
12612|					while (PUGI_IMPL_IS_CHARTYPE(*state, ct_space)) ++state;
12613|
12614|					if (*state != '(')
12615|						return parse_location_path();
12616|
12617|					// This looks like a function call; however this still can be a node-test. Check it.
12618|					if (parse_node_test_type(_lexer.contents()) != nodetest_none)
12619|						return parse_location_path();
12620|				}
12621|
12622|				xpath_ast_node* n = parse_filter_expression();
12623|				if (!n) return NULL;
12624|
12625|				if (_lexer.current() == lex_slash || _lexer.current() == lex_double_slash)
12626|				{
12627|					lexeme_t l = _lexer.current();
12628|					_lexer.next();
12629|
12630|					if (l == lex_double_slash)
12631|					{
12632|						if (n->rettype() != xpath_type_node_set)
12633|							return error("Step has to be applied to node set");
12634|
12635|						n = alloc_node(ast_step, n, axis_descendant_or_self, nodetest_type_node, NULL);
12636|						if (!n) return NULL;
12637|					}
12638|
12639|					// select from location path
12640|					return parse_relative_location_path(n);
12641|				}
12642|
12643|				return n;
12644|			}
12645|			else if (_lexer.current() == lex_minus)
12646|			{
12647|				_lexer.next();
12648|
12649|				// precedence 7+ - only parses union expressions
12650|				xpath_ast_node* n = parse_expression(7);
12651|				if (!n) return NULL;
12652|
12653|				return alloc_node(ast_op_negate, xpath_type_number, n);
12654|			}
12655|			else
12656|			{
12657|				return parse_location_path();
12658|			}
12659|		}
12660|
12661|		struct binary_op_t
12662|		{
12663|			ast_type_t asttype;
12664|			xpath_value_type rettype;
12665|			int precedence;
12666|
12667|			binary_op_t(): asttype(ast_unknown), rettype(xpath_type_none), precedence(0)
12668|			{
12669|			}
12670|
12671|			binary_op_t(ast_type_t asttype_, xpath_value_type rettype_, int precedence_): asttype(asttype_), rettype(rettype_), precedence(precedence_)
12672|			{
12673|			}
12674|
12675|			static binary_op_t parse(xpath_lexer& lexer)
12676|			{
12677|				switch (lexer.current())
12678|				{
12679|				case lex_string:
12680|					if (lexer.contents() == PUGIXML_TEXT("or"))
12681|						return binary_op_t(ast_op_or, xpath_type_boolean, 1);
12682|					else if (lexer.contents() == PUGIXML_TEXT("and"))
12683|						return binary_op_t(ast_op_and, xpath_type_boolean, 2);
12684|					else if (lexer.contents() == PUGIXML_TEXT("div"))
12685|						return binary_op_t(ast_op_divide, xpath_type_number, 6);
12686|					else if (lexer.contents() == PUGIXML_TEXT("mod"))
12687|						return binary_op_t(ast_op_mod, xpath_type_number, 6);
12688|					else
12689|						return binary_op_t();
12690|
12691|				case lex_equal:
12692|					return binary_op_t(ast_op_equal, xpath_type_boolean, 3);
12693|
12694|				case lex_not_equal:
12695|					return binary_op_t(ast_op_not_equal, xpath_type_boolean, 3);
12696|
12697|				case lex_less:
12698|					return binary_op_t(ast_op_less, xpath_type_boolean, 4);
12699|
12700|				case lex_greater:
12701|					return binary_op_t(ast_op_greater, xpath_type_boolean, 4);
12702|
12703|				case lex_less_or_equal:
12704|					return binary_op_t(ast_op_less_or_equal, xpath_type_boolean, 4);
12705|
12706|				case lex_greater_or_equal:
12707|					return binary_op_t(ast_op_greater_or_equal, xpath_type_boolean, 4);
12708|
12709|				case lex_plus:
12710|					return binary_op_t(ast_op_add, xpath_type_number, 5);
12711|
12712|				case lex_minus:
12713|					return binary_op_t(ast_op_subtract, xpath_type_number, 5);
12714|
12715|				case lex_multiply:
12716|					return binary_op_t(ast_op_multiply, xpath_type_number, 6);
12717|
12718|				case lex_union:
12719|					return binary_op_t(ast_op_union, xpath_type_node_set, 7);
12720|
12721|				default:
12722|					return binary_op_t();
12723|				}
12724|			}
12725|		};
12726|
12727|		xpath_ast_node* parse_expression_rec(xpath_ast_node* lhs, int limit)
12728|		{
12729|			binary_op_t op = binary_op_t::parse(_lexer);
12730|
12731|			while (op.asttype != ast_unknown && op.precedence >= limit)
12732|			{
12733|				_lexer.next();
12734|
12735|				if (++_depth > xpath_ast_depth_limit)
12736|					return error_rec();
12737|
12738|				xpath_ast_node* rhs = parse_path_or_unary_expression();
12739|				if (!rhs) return NULL;
12740|
12741|				binary_op_t nextop = binary_op_t::parse(_lexer);
12742|
12743|				while (nextop.asttype != ast_unknown && nextop.precedence > op.precedence)
12744|				{
12745|					rhs = parse_expression_rec(rhs, nextop.precedence);
12746|					if (!rhs) return NULL;
12747|
12748|					nextop = binary_op_t::parse(_lexer);
12749|				}
12750|
12751|				if (op.asttype == ast_op_union && (lhs->rettype() != xpath_type_node_set || rhs->rettype() != xpath_type_node_set))
12752|					return error("Union operator has to be applied to node sets");
12753|
12754|				lhs = alloc_node(op.asttype, op.rettype, lhs, rhs);
12755|				if (!lhs) return NULL;
12756|
12757|				op = binary_op_t::parse(_lexer);
12758|			}
12759|
12760|			return lhs;
12761|		}
12762|
12763|		// Expr ::= OrExpr
12764|		// OrExpr ::= AndExpr | OrExpr 'or' AndExpr
12765|		// AndExpr ::= EqualityExpr | AndExpr 'and' EqualityExpr
12766|		// EqualityExpr ::= RelationalExpr
12767|		//					| EqualityExpr '=' RelationalExpr
12768|		//					| EqualityExpr '!=' RelationalExpr
12769|		// RelationalExpr ::= AdditiveExpr
12770|		//					  | RelationalExpr '<' AdditiveExpr
12771|		//					  | RelationalExpr '>' AdditiveExpr
12772|		//					  | RelationalExpr '<=' AdditiveExpr
12773|		//					  | RelationalExpr '>=' AdditiveExpr
12774|		// AdditiveExpr ::= MultiplicativeExpr
12775|		//					| AdditiveExpr '+' MultiplicativeExpr
12776|		//					| AdditiveExpr '-' MultiplicativeExpr
12777|		// MultiplicativeExpr ::= UnaryExpr
12778|		//						  | MultiplicativeExpr '*' UnaryExpr
12779|		//						  | MultiplicativeExpr 'div' UnaryExpr
12780|		//						  | MultiplicativeExpr 'mod' UnaryExpr
12781|		xpath_ast_node* parse_expression(int limit = 0)
12782|		{
12783|			size_t old_depth = _depth;
12784|
12785|			if (++_depth > xpath_ast_depth_limit)
12786|				return error_rec();
12787|
12788|			xpath_ast_node* n = parse_path_or_unary_expression();
12789|			if (!n) return NULL;
12790|
12791|			n = parse_expression_rec(n, limit);
12792|
12793|			_depth = old_depth;
12794|
12795|			return n;
12796|		}
