12798|		xpath_parser(const char_t* query, xpath_variable_set* variables, xpath_allocator* alloc, xpath_parse_result* result): _alloc(alloc), _lexer(query), _query(query), _variables(variables), _result(result), _depth(0)
12799|		{
12800|		}
12801|
12802|		xpath_ast_node* parse()
12803|		{
12804|			xpath_ast_node* n = parse_expression();
12805|			if (!n) return NULL;
12806|
12807|			assert(_depth == 0);
12808|
12809|			// check if there are unparsed tokens left
12810|			if (_lexer.current() != lex_eof)
12811|				return error("Incorrect query");
12812|
12813|			return n;
12814|		}
12815|
12816|		static xpath_ast_node* parse(const char_t* query, xpath_variable_set* variables, xpath_allocator* alloc, xpath_parse_result* result)
12817|		{
12818|			xpath_parser parser(query, variables, alloc, result);
12819|
12820|			return parser.parse();
12821|		}
