12957|	PUGI_IMPL_FN void xpath_node_set::_assign(const_iterator begin_, const_iterator end_, type_t type_)
12958|	{
12959|		assert(begin_ <= end_);
12960|
12961|		size_t size_ = static_cast<size_t>(end_ - begin_);
12962|
12963|		// use internal buffer for 0 or 1 elements, heap buffer otherwise
12964|		xpath_node* storage = (size_ <= 1) ? _storage : static_cast<xpath_node*>(impl::xml_memory::allocate(size_ * sizeof(xpath_node)));
12965|
12966|		if (!storage)
12967|		{
12968|		#ifdef PUGIXML_NO_EXCEPTIONS
12969|			return;
12970|		#else
12971|			throw std::bad_alloc();
12972|		#endif
12973|		}
12974|
12975|		// deallocate old buffer
12976|		if (_begin != _storage)
12977|			impl::xml_memory::deallocate(_begin);
12978|
12979|		// size check is necessary because for begin_ = end_ = nullptr, memcpy is UB
12980|		if (size_)
12981|			memcpy(storage, begin_, size_ * sizeof(xpath_node));
12982|
12983|		_begin = storage;
12984|		_end = storage + size_;
12985|		_type = type_;
12986|	}
